(function () {
// 6 Antwortmöglichkeiten für Altklausuren und Holztrattner-Übungsfälle (ersetzt die 4er-Originale zur Laufzeit)
const A=(window.WPR&&window.WPR[16]&&window.WPR[16].cases)||[], R=window.WPRK_RH||[];
const SA={"0": {"c": 3, "o": [["Ist nur das Verpflichtungsgeschäft nach § 142 nichtig, ist V Eigentümer.", "Falsch. Dann bleibt die Übereignung wirksam, K ist Eigentümer."], ["Sind Verpflichtungs- und Verfügungsgeschäft nichtig, ist K Eigentümer.", "Falsch. Siehe d."], ["Sind beide nichtig, hat V einen Herausgabeanspruch nur aus § 812.", "Falsch. Daneben steht § 985 („nur“)."], ["Sind Verpflichtungs- und Verfügungsgeschäft nichtig, ist V Eigentümer.", "Richtig. Fehleridentität: Ohne wirksame Übereignung ist V Eigentümer geblieben."], ["Die Anfechtung erfasst stets nur das Verpflichtungsgeschäft, weil das Abstraktionsprinzip gilt.", "Falsch. Bei Fehleridentität, etwa bei arglistiger Täuschung, kann auch die Übereignung angefochten werden („stets“)."], ["Mit der Anfechtung wird der Kaufvertrag nur für die Zukunft beseitigt, erbrachte Leistungen bleiben.", "Falsch. Die Anfechtung wirkt zurück: Das Geschäft ist von Anfang an nichtig (§ 142 I)."]]}, "1": {"c": 1, "o": [["Nach § 195 in 3 Jahren ab Jahresende, am 31.12.2026.", "Falsch. Für Mängelrechte gilt § 438."], ["Am 09.05.2025, vier Monate nach dem ersten Auftreten des Mangels.", "Richtig. Der Mangel hat sich innerhalb der Frist gezeigt, Verjährung frühestens 4 Monate danach (§ 475e III)."], ["2 Jahre ab Ende des Entstehungsjahres, also 31.12.2025.", "Falsch. § 438 II: Beginn mit Ablieferung, nicht Jahresende."], ["2 Jahre ab Gefahrübergang, der Zeitpunkt des Eigentumsübergangs ist, also 10.03.2025.", "Falsch. Gefahrübergang ist die Übergabe, und § 475e III verlängert."], ["Am 10.03.2025, weil die zweijährige Frist mit der Ablieferung beginnt (§ 438 II).", "Falsch. Ohne § 475e III wäre das richtig. Weil sich der Mangel innerhalb der Frist gezeigt hat, tritt die Verjährung erst vier Monate nach dem ersten Auftreten ein."], ["Am 09.01.2027, weil die Verjährung mit der Entdeckung des Mangels neu beginnt (§ 212).", "Falsch. Die Entdeckung ist kein Neubeginn nach § 212."]]}, "2": {"c": 2, "o": [["G kann ohne Frist Schadensersatz statt der Leistung (teureres Ersatzgerät) verlangen.", "Falsch. § 281 I verlangt eine Frist zur Nacherfüllung."], ["G kann ohne Fristsetzung zurücktreten, weil ihm die Nacherfüllung durch L unzumutbar ist (§ 440).", "Falsch. Bloßer Unmut über L macht die Nacherfüllung nicht unzumutbar; es bleibt bei der Frist des § 323 I."], ["G muss L erst eine Frist zur Nacherfüllung setzen, bevor er Schadensersatz statt der Leistung verlangt.", "Richtig. Vorrang der Nacherfüllung."], ["L hat die Wahl zwischen Reparatur und Neulieferung, weil er als Verkäufer die Kosten trägt.", "Falsch. Der Käufer wählt (§ 439 I)."], ["G kann sofort mindern, weil die Minderung anders als der Rücktritt keine Frist voraussetzt (§ 441).", "Falsch. Die Minderung tritt „statt“ des Rücktritts ein (§ 441 I 1) und setzt ebenso eine Frist voraus."], ["G kann nur Schadensersatz neben der Leistung verlangen, weil L bloß leicht fahrlässig handelte.", "Falsch. Leichte Fahrlässigkeit genügt für das Vertretenmüssen (§ 276 I). Schadensersatz statt der Leistung scheitert hier nur an der fehlenden Frist."]]}, "3": {"c": 4, "o": [["Es wird vermutet, dass der Mangel schon bei Gefahrübergang vorlag.", "Falsch. § 477 I gilt nur ein Jahr, das ist hier vorbei."], ["G muss das Gerät auf eigene Kosten schicken, ohne Erstattung.", "Falsch. § 439 II: Der Verkäufer trägt die Transportkosten."], ["G muss erst eine Frist setzen, sonst ist die Reparatur nicht fällig.", "Falsch. Der Nacherfüllungsanspruch ist mit dem Verlangen fällig."], ["L kann die Reparatur wegen unverhältnismäßiger Transportkosten verweigern (§ 439 IV).", "Falsch. Transportkosten machen die Nacherfüllung nicht unverhältnismäßig; sie trägt ohnehin der Verkäufer (§ 439 II)."], ["G kann von L einen Vorschuss für die Kosten des Transports nach Lüneburg verlangen.", "Richtig. § 475 IV beim Verbrauchsgüterkauf."], ["Die Mängelrechte sind verjährt, weil seit der Lieferung mehr als ein Jahr vergangen ist.", "Falsch. Die Verjährung beträgt zwei Jahre (§ 438 I Nr. 3). Nur die Vermutung des § 477 I ist auf ein Jahr begrenzt."]]}, "4": {"c": 0, "o": [["Es handelt sich nicht um eine Ware mit digitalen Elementen, weil das Gerät auch ohne die KI kühlt.", "Richtig nach h. M.: Die Grundfunktion Kühlen geht auch manuell, das Digitale ist nicht funktionsnotwendig (§ 327a III). Es bleibt bei Kaufrecht für das Gerät."], ["Die §§ 327 ff. gelten für B2B-, B2C- und C2C-Verträge über digitale Produkte gleichermaßen.", "Falsch. Nur für Verbraucherverträge."], ["Die Gewährleistung richtet sich ausschließlich nach § 327i, weil die KI den Fehler verursacht hat.", "Falsch („ausschließlich“)."], ["P kann frei wählen, ob er nach §§ 474 ff. oder nach §§ 327 ff. vorgeht.", "Falsch. Das Gesetz ordnet zu, es gibt kein Wahlrecht."], ["Es liegt eine Ware mit digitalen Elementen vor, weil die Automatik ohne Software nicht funktioniert.", "Falsch (nach h. M.). Entscheidend ist, ob die Ware ihre Funktionen ohne das digitale Element erfüllen kann (§ 327a III). Kühlen geht auch manuell."], ["P hat keine Mängelrechte, weil die manuelle Einstellung weiter möglich und das Gerät daher mangelfrei ist.", "Falsch. Auch die Automatik gehört zur geschuldeten Funktion; ihr Versagen ist ein Mangel (§ 434)."]]}, "5": {"c": 5, "o": [["… zwei übereinstimmende Willenserklärungen.", "Falsch. Das ist der Vertragsschluss, nicht dessen wesentlicher Inhalt."], ["… Kaufpreis, Kaufgegenstand und Übergabeort.", "Falsch. Der Leistungsort ergibt sich notfalls aus § 269."], ["… Angebot, Annahme und Übergabe der Kaufsache.", "Falsch. Das sind Vertragsschluss und Erfüllung, nicht der wesentliche Vertragsinhalt."], ["… Kaufpreis, Kaufgegenstand und Zahlungsfrist.", "Falsch. Die Fälligkeit ergibt sich notfalls aus § 271."], ["… Kaufgegenstand, Kaufpreis und Gewährleistungsfrist.", "Falsch. Die Frist ist gesetzlich geregelt (§ 438)."], ["… Kaufpreis, Kaufgegenstand und Vertragspartner.", "Richtig."]]}, "6": {"c": 3, "o": [["Durch das Öffnen ist konkludent ein Kaufvertrag über alle benutzten Produkte zustande gekommen.", "Falsch. Die Ware im Regal ist invitatio, das Kaufhaus hat nichts angenommen."], ["Ein Kaufvertrag wäre anfechtbar, weil sie sich über die Tragweite ihres Handelns geirrt hat.", "Falsch. Rechtsfolgenirrtum ist unbeachtlich."], ["Sie kann ohne Fristsetzung vom Kaufvertrag zurücktreten, weil sie die Produkte nicht wollte.", "Falsch. Es gibt weder einen Vertrag noch einen Rücktrittsgrund."], ["Das Kaufhaus kann Schadensersatz aus §§ 280 I, 311 II, 241 II verlangen (Vertragsanbahnung).", "Richtig. Vertragsanbahnung, Verletzung der Rücksichtnahmepflicht."], ["Das Kaufhaus kann den Kaufpreis verlangen, weil V das Angebot durch Öffnen angenommen hat (§ 151).", "Falsch. Die Ware im Regal ist kein Angebot; ein Vertrag besteht nicht."], ["Das Kaufhaus hat keine vertraglichen Ansprüche, weil noch kein Vertrag geschlossen war.", "Falsch. Schon die Vertragsanbahnung begründet ein Schuldverhältnis mit Rücksichtnahmepflichten (§ 311 II Nr. 2)."]]}, "7": {"c": 0, "o": [["Für die Anpassung sind die Umstände bei Vertragsschluss mit denen danach zu vergleichen.", "Richtig."], ["Eine nachträgliche Anpassung eines wirksamen Vertrages ist nicht möglich.", "Falsch. § 313 erlaubt sie."], ["G kann die Anpassung verlangen, weil seine Einnahmen tatsächlich gesunken sind (§ 313 I).", "Falsch. Seine verschwiegenen Einkünfte sind nicht Geschäftsgrundlage geworden. Eine einseitige Kürzung gibt es ohnehin nicht."], ["Die Belange des Kindes werden bei der Anpassung nach § 313 nicht berücksichtigt.", "Falsch. § 313 verlangt eine Abwägung der Zumutbarkeit."], ["G darf die Zahlung einseitig kürzen; einer Anpassung durch Vertrag oder Urteil bedarf es nicht.", "Falsch. § 313 I gibt einen Anspruch auf Anpassung, kein Recht zur einseitigen Kürzung."], ["G kann den Vertrag anfechten, weil er sich über seine künftigen Einnahmen geirrt hat (§ 119 II).", "Falsch. Ein Irrtum über künftige Entwicklungen ist ein unbeachtlicher Motivirrtum."]]}, "8": {"c": 2, "o": [["Ein Vertragsschluss per E-Mail genügt der Schriftform des § 126 I.", "Falsch. E-Mail ist Textform."], ["Die Schriftform kann ausnahmslos durch die elektronische Form ersetzt werden.", "Falsch. § 126 III und § 623 schließen sie aus."], ["Die Kündigung eines Arbeitsverhältnisses bedarf der Schriftform.", "Richtig. § 623 BGB."], ["Ein Testament muss immer notariell beurkundet oder beglaubigt werden.", "Falsch. Eigenhändiges Testament, § 2247."], ["Ein Mietvertrag über Wohnraum ist ohne Schriftform nichtig.", "Falsch. Fehlt die Schriftform bei langfristiger Miete, gilt der Vertrag auf unbestimmte Zeit (§ 550)."], ["Eine Bürgschaft eines Privatmanns kann wirksam per E-Mail erklärt werden.", "Falsch. § 766 S. 1, 2: Schriftform, die elektronische Form ist ausgeschlossen."]]}, "9": {"c": 4, "o": [["Nein, die Einlagerung war eine freiwillige Aufwendung und kein ersatzfähiger Schaden.", "Falsch. § 304 erfasst gerade Mehraufwendungen."], ["Nein, V muss den Tisch erneut anliefern und die Lagerkosten selbst tragen.", "Falsch. Nicht entscheidend."], ["Nur wenn K eine Anzahlung geleistet hat, weil V sonst kein Sicherungsinteresse hat.", "Falsch. Keine solche Voraussetzung."], ["Ja, aber nur, wenn K den Termin schuldhaft versäumt hat (§§ 280 I, 276).", "Falsch. Annahmeverzug setzt kein Verschulden voraus."], ["Ja, K war in Annahmeverzug; Mehraufwendungen sind zu ersetzen (§ 304).", "Richtig. §§ 293, 294, 304."], ["Nein, weil V die Lieferung vorher hätte ankündigen müssen (§ 299).", "Falsch. § 299 gilt nur bei unbestimmter Leistungszeit; hier war 15 Uhr vereinbart."]]}, "10": {"c": 5, "o": [["Nein, ohne Lieferung des Tisches gibt es keinesfalls einen Kaufpreisanspruch.", "Falsch („keinesfalls“). § 326 II."], ["Nein, weil K am Hochwasser kein Verschulden trifft (§ 326 II 1 Alt. 1).", "Falsch. Auf Verschulden des K kommt es nicht an."], ["Nein, weil K bei der Einlagerung nicht mehr in Annahmeverzug war.", "Falsch. Der Annahmeverzug dauerte an."], ["Ja, aber nur zur Hälfte, weil keine Partei das Hochwasser zu vertreten hat.", "Falsch. § 326 II 1 Alt. 2: Der volle Preis bleibt geschuldet."], ["Nein, weil V den Tisch selbst hätte lagern müssen und für die Einlagerung bei X haftet.", "Falsch. Das Hochwasser hat niemand zu vertreten; im Annahmeverzug haftet V ohnehin nur für Vorsatz und grobe Fahrlässigkeit (§ 300 I)."], ["Ja, weil der Tisch während des Annahmeverzugs ohne Verschulden des V unterging (§ 326 II).", "Richtig. Unmöglichkeit während des Annahmeverzugs ohne Vertretenmüssen des V: Der Preisanspruch bleibt (§ 326 II 1 Alt. 2, § 300 I)."]]}, "11": {"c": 1, "o": [["Es handelt sich um eine Ware mit digitalem Element.", "Falsch. Reine Software ist ein digitales Produkt."], ["S kann den Vertrag beenden und den gezahlten Preis zurückfordern (§§ 327m, 327o).", "Richtig. Digitales Produkt: Vertragsbeendigung nach § 327m I, weil F die Nacherfüllung verweigert, Rückzahlung nach § 327o."], ["Es gelten ausschließlich die §§ 434 ff., weil S die Software gekauft hat.", "Falsch. §§ 327 ff. gelten."], ["Nur der Hersteller der Software schuldet Nacherfüllung, nicht F.", "Falsch. Vertragspartner ist F."], ["S muss F zuerst eine weitere Frist setzen, weil die Weigerung allein nicht genügt.", "Falsch. Verweigert der Unternehmer die Herstellung des vertragsgemäßen Zustands, kann der Verbraucher den Vertrag ohne Weiteres beenden (§ 327m I)."], ["S kann nur mindern, weil eine Vertragsbeendigung bei Software ausgeschlossen ist.", "Falsch. § 327m ermöglicht die Vertragsbeendigung."]]}, "12": {"c": 3, "o": [["S kann Zahlung und Abnahme verlangen, weil er die Möbel noch angeboten hat (§ 433 II).", "Falsch. Nach Fristablauf und Rücktritt bzw. Schadensersatzverlangen ist der Erfüllungsanspruch weg (§ 281 IV)."], ["D hat keinen Anspruch auf die 300 €, weil er die Möbel woanders gekauft hat.", "Falsch. Siehe d."], ["Es bestehen keine gegenseitigen Ansprüche mehr, weil D den Vertrag beendet hat.", "Falsch. Siehe d."], ["S kann weder Zahlung noch Abnahme verlangen, D aber die 300 € Mehrkosten.", "Richtig. §§ 280 I, III, 281, Rücktritt und Schadensersatz nebeneinander (§ 325)."], ["D kann die 300 € verlangen, S aber trotzdem Zahlung und Abnahme der Möbel.", "Falsch. Mit dem Rücktritt bzw. dem Verlangen von Schadensersatz statt der Leistung ist der Erfüllungsanspruch ausgeschlossen (§ 281 IV)."], ["D kann die 300 € nur verlangen, wenn er zuvor eine zweite Frist gesetzt hat.", "Falsch. Eine angemessene Frist genügt (§ 281 I)."]]}, "13": {"c": 1, "o": [["R haftet nur aus § 823 I, weil § 229 StGB als Strafnorm im Zivilrecht nicht gilt.", "Falsch („nur“). Daneben § 823 II und § 7 StVG."], ["R haftet aus § 823 I und II für Heilbehandlung und Schmerzensgeld.", "Richtig. Schmerzensgeld nach § 253 II."], ["M kann nur entweder Heilbehandlung oder Schmerzensgeld verlangen.", "Falsch. Beides nebeneinander."], ["Die Rechtswidrigkeit fehlt, weil R nicht vorsätzlich gehandelt hat.", "Falsch. Sie ist indiziert, kein Rechtfertigungsgrund."], ["M bekommt die Heilbehandlungskosten, Schmerzensgeld aber nur bei vorsätzlicher Verletzung.", "Falsch. § 253 II setzt keinen Vorsatz voraus."], ["R haftet nicht, weil M als Fußgängerin am Zebrastreifen selbst aufpassen musste (§ 254).", "Falsch. Ein Mitverschulden ist nicht ersichtlich; am Zebrastreifen hat M Vorrang."]]}, "14": {"c": 2, "o": [["Nein, weil § 305 II mangels ausdrücklichen Hinweises vor Vertragsschluss nicht erfüllt ist.", "Falsch begründet. § 305 II gilt gegenüber Unternehmern nicht (§ 310 I)."], ["Ja, weil § 305 II durch die Übergabe der AGB erfüllt ist.", "Falsch. § 305 II ist nicht anwendbar."], ["Nein, weil der Hinweis erst nach der mündlichen Einigung kam und der Vertrag schon stand.", "Richtig. Der Vertrag war schon geschlossen, ein nachträglicher Hinweis bezieht nichts mehr ein."], ["Ja, unter Unternehmern genügt der Hinweis nach Vertragsschluss.", "Falsch. Auch B2B braucht es eine Einigung bei Vertragsschluss."], ["Ja, weil Ziegelhändler branchenüblich nach AGB liefern und das jeder Kaufmann weiß.", "Falsch. Branchenüblichkeit ersetzt die Einbeziehung bei Vertragsschluss nicht."], ["Nein, weil AGB unter Kaufleuten nur mit einem kaufmännischen Bestätigungsschreiben gelten.", "Falsch. Unter Kaufleuten genügt jede, auch stillschweigende, Einbeziehung bei Vertragsschluss."]]}, "15": {"c": 0, "o": [["Die Frist läuft erst am Dienstag, 4.6., ab; K kann noch widerrufen.", "Richtig. Fristbeginn 22.5. (§ 187 I), 14 Tage, Ende 4.6., 24 Uhr."], ["Die Frist ist am Mittwoch, 29.5., abgelaufen, weil sie mit der Bestellung begann.", "Falsch. Beginn ist der Erhalt der Ware, nicht die Bestellung."], ["Die Frist ist am Dienstag, 28.5., abgelaufen, eine Woche nach der Lieferung.", "Falsch. Das wären nur 7 Tage."], ["Die Frist läuft am Montag, 3.6., ab, weil der Liefertag mitzählt.", "Falsch. Der Tag des Erhalts zählt nicht mit (§ 187 I)."], ["Die Frist läuft erst am 21.6. ab, weil sie bei Fernabsatz einen Monat beträgt.", "Falsch. Sie beträgt 14 Tage (§ 355 II 1)."], ["Die Frist ist abgelaufen, weil sie bei Online-Käufen mit dem Vertragsschluss beginnt (§ 355 II 2).", "Falsch. Beim Warenkauf beginnt sie mit Erhalt der Ware (§ 356 II Nr. 1 a)."]]}, "16": {"c": 4, "o": [["Kein Anspruch, A war angetrunken und daher geschäftsunfähig.", "Falsch. Angetrunken heißt nicht dauerhaft geschäftsunfähig, das Aushängen geschah ohnehin später."], ["Kein Anspruch, B hat das Angebot nicht angenommen.", "Falsch. Bei der Auslobung braucht es keine Annahme."], ["Anspruch, B hat konkludent nach § 151 angenommen.", "Falsch. Kein Vertrag, sondern einseitiges Rechtsgeschäft."], ["Anspruch auf 100 €, aber nur, wenn B von der Auslobung wusste, als er den Ohrring zurückgab.", "Falsch. § 657 Hs. 2: auch wenn der Handelnde nicht mit Rücksicht auf die Auslobung gehandelt hat."], ["Anspruch auf 100 €, weil es sich um eine Auslobung handelt (§ 657).", "Richtig. § 657 BGB, auch ohne Kenntnis der Auslobung."], ["Kein Anspruch auf 100 €, sondern nur auf den gesetzlichen Finderlohn (§ 971).", "Falsch. Die Auslobung gibt den versprochenen Betrag („nur“)."]]}, "17": {"c": 5, "o": [["K kann gegen 1.000 € Lieferung verlangen, V kann als Unternehmer nicht widerrufen.", "Falsch. Es geht nicht um ein Verbraucher-Widerrufsrecht."], ["K kann gegen 1.000 € Lieferung verlangen, weil V sorgfältig formulieren muss.", "Falsch. Anfechtung setzt kein fehlendes Verschulden voraus."], ["Es fehlt an einer Anfechtungserklärung, weil V nur „widerrufe“ geschrieben hat.", "Falsch. Das Wort muss nicht fallen (§ 133)."], ["Ein Vertrag über 1.200 € ist zustande gekommen, weil V diesen Preis gewollt hat (§ 133).", "Falsch. Maßgeblich ist der objektive Empfängerhorizont; erklärt waren 1.000 €."], ["V kann anfechten, muss K aber die Differenz von 200 € als Schaden ersetzen (§ 122).", "Falsch. § 122 ersetzt nur den Vertrauensschaden, nicht das Erfüllungsinteresse."], ["K hat keinen Anspruch auf Lieferung für 1.000 €, weil V wirksam angefochten hat.", "Richtig. Erklärungsirrtum (§ 119 I Var. 2), „widerrufe“ ist als Anfechtung auszulegen."]]}, "18": {"c": 1, "o": [["Ersatz der Vertragsstrafe ja, der Mietkosten nein, weil Kilian hätte warten müssen.", "Falsch. Beides ist Verzögerungsschaden."], ["Ersatz der Vertragsstrafe und zusätzlich der Mietkosten vom 23. bis 27.6. (§§ 280 I, II, 286).", "Richtig. Verzug ab 16.6. ohne Mahnung (§ 286 II Nr. 1), Schaden nach §§ 280 I, II, 286."], ["Nur die Mietkosten vom 23. bis 27.6., weil die Vertragsstrafe nicht vorhersehbar war.", "Falsch. Kilian hat auf die Vertragsstrafe hingewiesen; sie ist ersatzfähiger Verzögerungsschaden."], ["Kein Ersatz, weil kein relatives Fixgeschäft vereinbart war (§ 323 II Nr. 2).", "Falsch. Für den Verzögerungsschaden braucht es kein Fixgeschäft."], ["Kein Ersatz, weil Vera erst nach einer Mahnung in Verzug geriet und die Frist bis 21.6. lief.", "Falsch. Mit dem kalendermäßigen Termin 15.6. trat Verzug ohne Mahnung ein (§ 286 II Nr. 1)."], ["Vertragsstrafe und Mietkosten, aber nur zur Hälfte wegen Mitverschuldens (§ 254).", "Falsch. Ein Mitverschulden des Kilian ist nicht ersichtlich."]]}, "19": {"c": 2, "o": [["Am 10. März um 14 Uhr, weil eine E-Mail schon mit dem Absenden zugeht.", "Falsch. Absenden ist Abgabe, nicht Zugang."], ["Am 17. März um 9 Uhr, weil der Mitarbeiter erst dann wieder im Dienst ist.", "Falsch. Krankheit fällt in die Risikosphäre des Empfängers."], ["Am 10. März, als die E-Mail im Postfach des Autohauses abrufbar war.", "Richtig. Machtbereich des Empfängers, Kenntnisnahme während der Geschäftszeit zu erwarten."], ["Am 14. März um 11 Uhr, als der Mitarbeiter die E-Mail tatsächlich gelesen hat.", "Falsch. Krankheit fällt in die Risikosphäre des Empfängers."], ["Am 11. März zu Geschäftsbeginn, weil E-Mails stets erst am Folgetag zugehen.", "Falsch. Eine E-Mail, die während der Geschäftszeit eingeht, geht noch am selben Tag zu."], ["Gar nicht, weil die E-Mail nicht an den zuständigen Mitarbeiter persönlich gerichtet war.", "Falsch. Maßgeblich ist der Machtbereich des Empfängers, also des Autohauses."]]}, "20": {"c": 3, "o": [["Nein, die essentialia negotii sind unvollständig, weil die Fahrzeugdaten fehlen.", "Falsch. Sache, Preis und Parteien stehen fest."], ["Ja, weil Max ein rechtsverbindliches Angebot über 8.890 € abgegeben hat.", "Falsch. Ein Angebot allein ist noch kein Vertrag."], ["Ja, Max hat das Angebot des Autohauses mit seiner E-Mail angenommen.", "Falsch. Siehe d."], ["Nein, weil das Inserat kein verbindliches Angebot im Sinne des § 145 ist.", "Richtig. Invitatio ad offerendum. Max hat ein Angebot gemacht, die Annahme fehlt."], ["Ja, weil das Autohaus die E-Mail am selben Tag erhalten und nicht widersprochen hat.", "Falsch. Schweigen ist keine Annahme."], ["Nein, weil Kaufverträge über Kraftfahrzeuge schriftlich geschlossen werden müssen.", "Falsch. Der Kauf ist formfrei."]]}, "21": {"c": 4, "o": [["Wegen des Vorrangs der Naturalrestitution kommt nur eine Reparatur in Betracht.", "Falsch. Bei Unmöglichkeit Geld (§ 251)."], ["Die GmbH kann nach dem ProdHaftG Ersatz für den zerstörten Reiniger verlangen.", "Falsch. Das ProdHaftG ersetzt nicht das Produkt selbst und nur privat genutzte Sachen."], ["Die GmbH hat keinen Anspruch auf Schadensersatz, sondern nur auf Nacherfüllung.", "Falsch. § 437 Nr. 3 ist möglich."], ["Martin hat keinen Anspruch, weil er den Reiniger nicht selbst gekauft hat.", "Falsch. § 823 I und das ProdHaftG setzen keinen Vertrag voraus."], ["Der Tatbestand des § 823 I ist zugunsten von Martin erfüllt (Produzentenhaftung).", "Richtig. Körperverletzung durch Verletzung der Herstellerpflichten, Verschulden bei erkennbarem Fehler."], ["Die OHG haftet Martin nur, wenn sie die Endkontrolle vorsätzlich unterlassen hat.", "Falsch. Fahrlässigkeit genügt (§ 823 I); nach dem ProdHaftG kommt es auf Verschulden gar nicht an."]]}, "22": {"c": 5, "o": [["§ 823 I ist erfüllt, die Kosten der Arbeitsunfähigkeit sind aber nicht ersatzfähig.", "Falsch. Die GmbH hat einen Weg zum Ersatz, siehe f."], ["Nach ProdHaftG muss sie beweisen, dass die Endkontrolle die Explosion verhindert hätte.", "Falsch. Das ProdHaftG ist verschuldensunabhängig."], ["Hätte ein Zulieferer das Teil hergestellt, haftet Müller & Söhne nicht nach ProdHaftG.", "Falsch. Auch der Endhersteller ist Hersteller (§ 4 I)."], ["Die GmbH kann die Kosten nur verlangen, wenn Martin selbst auf seine Ansprüche verzichtet.", "Falsch. Bei Entgeltfortzahlung geht Martins Anspruch kraft Gesetzes auf die GmbH über (§ 6 EFZG); ein Verzicht ist nicht nötig."], ["Die GmbH kann die Kosten nach dem ProdHaftG verlangen, weil sie den Reiniger gewerblich nutzt.", "Falsch. Das ProdHaftG ersetzt Sachschäden nur an privat genutzten Sachen; ein eigener Vermögensschaden der GmbH fällt nicht darunter."], ["Die GmbH hat einen Anspruch auf Ersatz der Kosten der Arbeitsunfähigkeit.", "Richtig. Aus dem Kaufvertrag (§§ 437 Nr. 3, 280 I, Mangelfolgeschaden), zudem geht Martins Anspruch auf Verdienstausfall bei Lohnfortzahlung auf die GmbH über (§ 6 EFZG)."]]}, "23": {"c": 0, "o": [["1, 2, 5", "Richtig. Nacherfüllung braucht Kaufvertrag und Sachmangel. Vertretenmüssen nur beim Schadensersatz."], ["1, 3, 5", "Falsch. Ohne Mangel kein Nacherfüllungsanspruch, Verschulden ist keine Voraussetzung."], ["1, 2, 3, 5", "Falsch. Punkt 3 gehört nicht in die Prüfung der Nacherfüllung."], ["1, 3, 4, 5", "Falsch. Gattungsschuld spielt keine Rolle."], ["1, 2, 4, 5", "Falsch. Ob Gattungs- oder Stückschuld, spielt für die Entstehung des Anspruchs keine Rolle."], ["2, 3, 5", "Falsch. Ohne Kaufvertrag gibt es keinen Anspruch, und Verschulden ist keine Voraussetzung."]]}, "24": {"c": 1, "o": [["Lukas hat einen Anspruch auf Übereignung des Armbands aus § 433 I.", "Falsch. Die Reservierung galt nur bis 16 Uhr."], ["Lukas hat keine Ansprüche, weil die Reservierung um 16 Uhr endete.", "Richtig. Die befristete Reservierung ist mit Ablauf des Zeitfensters erloschen, danach durfte Sophie frei verkaufen."], ["Lukas kann 10 € Schadensersatz statt der Leistung verlangen.", "Falsch. Sophie hat keine Pflicht verletzt."], ["Lukas muss Sophie erst eine Frist zur Nacherfüllung setzen.", "Falsch. Es geht nicht um einen Mangel."], ["Lukas kann von Sophie die 50 € Erlös aus dem Verkauf herausverlangen (§ 285).", "Falsch. Ein Anspruch auf das Armband bestand nach 16 Uhr nicht mehr; also gibt es auch kein Surrogat."], ["Sophie muss Lukas ein gleichwertiges Armband beschaffen, weil sie es reserviert hatte.", "Falsch. Es war ein Einzelstück, und die Reservierung war erloschen."]]}, "25": {"c": 3, "o": [["Er zahlt mit 5 % Rabatt, weil seine E-Mail ein kaufmännisches Bestätigungsschreiben ist.", "Falsch. Ein Bestätigungsschreiben gibt nur das Verhandelte wieder, der Rabatt war nie Thema. GreenHarvest hat widersprochen."], ["Kein Vertrag, weil sich die Parteien über den Preis nicht geeinigt haben (§ 155).", "Falsch. Der Vertrag kam am 11.1. zustande."], ["Seine E-Mail vom nächsten Morgen ist ein bindendes abänderndes Angebot (§ 150 II).", "Falsch. Einen geschlossenen Vertrag kann er nicht einseitig ändern; § 150 II betrifft nur die Annahme."], ["Er zahlt den Preis aus der Informations-E-Mail ohne Rabatt, weil der Vertrag so zustande kam.", "Richtig."], ["Er kann den Vertrag anfechten, weil er sich über den Rabatt geirrt hat (§ 119 I).", "Falsch. Erwartungen über einen Rabatt sind ein unbeachtlicher Motivirrtum."], ["Er zahlt mit 5 % Rabatt, weil Rabatte unter Kaufleuten handelsüblich sind (§ 346 HGB).", "Falsch. Ein Handelsbrauch für einen Rabatt ist nicht ersichtlich."]]}, "26": {"c": 2, "o": [["Bei ordnungsgemäßer Belehrung, wenn der Laptop mangelhaft ist.", "Falsch. Die Frist endete am 28.12., ein Mangel verlängert sie nicht."], ["Bei ordnungsgemäßer Belehrung, wenn er den Laptop erst am 16.12. ausgepackt hat.", "Falsch. Maßgeblich ist der Erhalt."], ["Wenn er nicht ordnungsgemäß über sein Widerrufsrecht belehrt wurde.", "Richtig. Dann hat die Frist nicht begonnen (§ 356 III)."], ["In allen genannten Fällen, weil die Frist erst am 31.12. endet.", "Falsch. Bei ordnungsgemäßer Belehrung endete sie am 28.12."], ["Bei ordnungsgemäßer Belehrung, wenn er den Vertrag erst am 16.12. per E-Mail bestätigt hat.", "Falsch. Maßgeblich ist der Erhalt der Ware am 14.12."], ["Bei ordnungsgemäßer Belehrung, weil die Frist für Online-Käufe einen Monat beträgt.", "Falsch. Sie beträgt 14 Tage (§ 355 II 1)."]]}, "27": {"c": 0, "o": [["1, 4, 7, 8", "Richtig. Schadensersatz (§§ 280 I, 282) und Rücktritt (§ 324)."], ["1, 2, 6, 7", "Falsch. 2 und 6 sind falsch."], ["1, 3, 5, 8", "Falsch. 3 und 5 sind falsch."], ["1, 4, 5, 8", "Falsch. 5 ist falsch, die Abnahme ist keine Rücksichtnahmepflicht nach § 241 II."], ["1, 4, 5, 7", "Falsch. 5 ist falsch."], ["1, 2, 7, 8", "Falsch. 2 ist falsch: Nebenpflichten bestehen auch bei Verträgen."]]}, "28": {"c": 5, "o": [["Personen über 18 können beschränkt geschäftsfähig sein, wenn sie unter Betreuung stehen.", "Falsch. Beschränkt geschäftsfähig sind nur Minderjährige (§ 106). Eine Betreuung ändert die Geschäftsfähigkeit nicht."], ["Ein Kind am Tag vor seinem 7. Geburtstag verkauft wirksam sein Kuscheltier, wenn die Eltern einwilligen.", "Falsch. Es ist noch geschäftsunfähig (§§ 104 Nr. 1, 105 I)."], ["Volljährige Geschäftsunfähige können keinerlei Rechtsgeschäfte tätigen und brauchen immer einen Betreuer.", "Falsch. § 105a, „keinerlei“ und „immer“."], ["Ein 17-Jähriger kann ohne Zustimmung seiner Eltern wirksam einen Handyvertrag abschließen.", "Falsch. Der Vertrag ist nicht lediglich rechtlich vorteilhaft (§§ 107, 108)."], ["Ein 16-Jähriger ist für Geschäfte des täglichen Lebens bereits voll geschäftsfähig.", "Falsch. Er ist beschränkt geschäftsfähig (§ 106); § 105a betrifft nur volljährige Geschäftsunfähige."], ["Verkauft K am Tag nach seinem 7. Geburtstag sein Kuscheltier an einen 8-Jährigen, ist das schwebend unwirksam.", "Richtig. Für beide nicht lediglich vorteilhaft, § 108."]]}, "29": {"c": 4, "o": [["Mit Abschluss des Kaufvertrages wird F Inhaber der Forderungen.", "Falsch. Trennungsprinzip, der Kaufvertrag verpflichtet nur."], ["F wird Inhaber durch Übergabe der Liste nach § 929.", "Falsch. § 929 gilt für bewegliche Sachen."], ["F wird Inhaber durch einseitige Erklärung des Z und Zahlung.", "Falsch. Die Abtretung ist ein Vertrag."], ["F wird Inhaber erst, wenn die Patienten über die Abtretung benachrichtigt wurden.", "Falsch. Die Abtretung ist ohne Anzeige wirksam; die Anzeige schützt nur den Schuldner (§ 407)."], ["F wird Inhaber durch eine Abtretungsvereinbarung mit Z (§ 398).", "Richtig. § 398."], ["F wird Inhaber durch Eintragung der Abtretung in ein öffentliches Register.", "Falsch. Ein solches Register gibt es für Forderungen nicht."]]}, "30": {"c": 2, "o": [["Die Schenkung ist als unzulässiges Insichgeschäft (§ 181) nichtig.", "Falsch. Der Schenkungsvertrag ist lediglich vorteilhaft, und § 181 führt nicht zur Nichtigkeit."], ["Die Schenkung ist ein einseitiges Rechtsgeschäft, das T nicht annehmen muss.", "Falsch. Sie ist ein Vertrag (§ 516)."], ["T braucht für den Schenkungsvertrag keine Vertretung, weil er lediglich vorteilhaft ist.", "Richtig. § 107."], ["Auch die Übereignung des vermieteten Grundstücks ist lediglich vorteilhaft.", "Falsch. Eintritt in die Mietverträge (§ 566) ist ein rechtlicher Nachteil."], ["Die Eltern können den Vertrag als Vertreter mit sich selbst schließen, weil § 181 hier nie gilt.", "Falsch („nie“). § 181 gilt grundsätzlich; nur lediglich vorteilhafte Geschäfte sind ausgenommen."], ["Für Schenkung und Übereignung genügt die Zustimmung der Tochter, weil sie 17 ist.", "Falsch. Für die nachteilige Übereignung braucht T die Mitwirkung eines Vertreters."]]}, "31": {"c": 1, "o": [["Grundstück und Gebäude werden in zwei Rechtsgeschäften übertragen.", "Falsch. Das Haus ist wesentlicher Bestandteil (§§ 94, 946)."], ["Einigung in notarieller Form (Auflassung) und Eintragung ins Grundbuch.", "Richtig. §§ 873, 925."], ["Einigung in Schriftform, ersetzbar durch E-Mail, und Eintragung.", "Falsch. Die Auflassung muss vor dem Notar erklärt werden (§ 925)."], ["„Auflassung“ ist die notarielle Einigung im Rahmen der Schenkung.", "Falsch. Auflassung ist die dingliche Einigung, nicht der Schenkungsvertrag."], ["Für die Übereignung genügt der notarielle Schenkungsvertrag; eine Eintragung ist nur deklaratorisch.", "Falsch. Die Eintragung ist konstitutiv (§ 873 I)."], ["Einigung und Übergabe des Hausschlüssels genügen, weil das Haus eine bewegliche Sache ist.", "Falsch. Grundstücke werden nach §§ 873, 925 übertragen."]]}, "32": {"c": 0, "o": [["Sie sind grundsätzlich zulässig, diese ist aber mangels Einhaltung des § 476 I 2 unwirksam.", "Richtig. Keine eigene Information vor Vertragsschluss, keine ausdrückliche und gesonderte Vereinbarung."], ["Negative Beschaffenheitsvereinbarungen sind nur zwischen Unternehmern zulässig.", "Falsch. § 476 I 2 erlaubt sie unter Voraussetzungen."], ["Sie sind im Verbrauchsgüterkauf immer unzulässig.", "Falsch („immer“)."], ["Es ist eine individuelle Absprache, die die Gewährleistung wirksam ausschließt.", "Falsch. § 476 I 1."], ["Sie ist wirksam, weil sie schriftlich im Vertrag steht und V unterschrieben hat.", "Falsch. Unterschrift genügt nicht; nötig sind eigene Information und eine ausdrückliche, gesonderte Vereinbarung (§ 476 I 2)."], ["Sie ist wirksam, weil bei Handarbeiten nach § 434 III gar keine objektiven Anforderungen gelten.", "Falsch. Auch Handarbeiten müssen den objektiven Anforderungen genügen, etwa einen funktionierenden Verschluss haben."]]}, "33": {"c": 3, "o": [["… den vollen Vertrauensschaden von 3.000 € verlangen, weil er B abgesagt hat.", "Falsch. Gedeckelt durch das Erfüllungsinteresse."], ["… nichts verlangen, wenn K kein Verschulden am Irrtum trifft.", "Falsch. § 122 ist verschuldensunabhängig."], ["… nur die Rückabwicklung des Kaufvertrags verlangen (§ 812).", "Falsch. Daneben § 122."], ["… nur 2.000 € verlangen, weil das Erfüllungsinteresse § 122 I begrenzt.", "Richtig. 5.000 € − 3.000 € = 2.000 €."], ["… 1.000 € verlangen, nämlich die Differenz zwischen beiden Angeboten.", "Falsch. Der Vertrauensschaden beträgt 3.000 € (entgangenes Geschäft mit B), begrenzt durch das Erfüllungsinteresse von 2.000 € (§ 122 I)."], ["… 5.000 € verlangen, weil er so steht, als wäre der Vertrag erfüllt worden.", "Falsch. § 122 ersetzt nicht das Erfüllungsinteresse."]]}, "34": {"c": 4, "o": [["Nein, Genio ist frei geworden und kann deshalb auch keinen Preis verlangen.", "Falsch. § 326 II."], ["Nein, weil Genio das Bild nicht tatsächlich angeboten hat (§ 294).", "Falsch. § 296 macht das Angebot entbehrlich."], ["Nein, weil anfängliche Unmöglichkeit den Vertrag unwirksam macht.", "Falsch. Nachträglich, und selbst anfänglich bliebe der Vertrag wirksam (§ 311a I)."], ["Ja, aber nur, wenn Jan den Termin schuldhaft versäumt hat.", "Falsch. Annahmeverzug setzt kein Verschulden voraus."], ["Ja, Jan hat nicht wie vereinbart abgeholt, und Genio trifft kein Verschulden.", "Richtig. Annahmeverzug ohne Angebot (§ 296, Abholtermin nach dem Kalender), Preisgefahr bei Jan (§ 326 II 1 Alt. 2)."], ["Ja, weil die Gefahr bei Kunstwerken schon mit Vertragsschluss übergeht.", "Falsch. Eine solche Regel gibt es nicht; Grundlage ist § 326 II 1 Alt. 2."]]}, "35": {"c": 5, "o": [["… gelten für digitale Produkte und für Waren mit digitalen Elementen.", "Falsch. Für digitale Produkte gelten §§ 327 ff."], ["… ersetzen den Sachmangelbegriff des § 434 vollständig.", "Falsch. Sie ergänzen ihn."], ["… gelten nicht, weil sie nur in einer EU-Richtlinie stehen.", "Falsch. Die Richtlinie wurde ins BGB umgesetzt."], ["… gelten nur für Kaufverträge zwischen zwei Unternehmern.", "Falsch. Sie gelten beim Verbrauchsgüterkauf."], ["… gelten auch für Waren ohne digitale Elemente, wenn sie elektrisch betrieben werden.", "Falsch. Sie betreffen nur Waren mit digitalen Elementen."], ["… ergänzen § 434 für Waren mit digitalen Elementen, vor allem um Updates.", "Richtig."]]}, "36": {"c": 5, "o": [["Nein, weil der Passus keine Allgemeine Geschäftsbedingung ist.", "Falsch. Vorformuliert für eine Vielzahl von Verträgen."], ["Nein, wenn A die erste Kundin wäre, weil dann keine AGB vorlägen.", "Falsch. Es reicht die Absicht der mehrfachen Verwendung."], ["Ja, die AGB schließt die Haftung für leichte Fahrlässigkeit wirksam aus.", "Falsch. Siehe f."], ["Nein, aber F haftet nur für die Behandlungskosten, nicht für Schmerzensgeld.", "Falsch. Schmerzensgeld nach § 253 II gilt auch im Vertrag."], ["Ja, weil A beim Training auf eigene Gefahr handelt und selbst hätte aufpassen müssen.", "Falsch. Ein Handeln auf eigene Gefahr liegt nicht vor; F hat das Laufband falsch eingestellt."], ["Nein. Die AGB ist unwirksam, F haftet auch bei leichter Fahrlässigkeit.", "Richtig. § 309 Nr. 7a, Körperverletzung."]]}, "37": {"c": 1, "o": [["Ja, wenn S nicht sorgfältig ausgewählt oder überwacht wurde.", "Falsch. § 831 verlangt Handeln in Ausführung der Verrichtung."], ["Nein, R haftet nicht dafür, dass S ihren Zugang nutzt, um einen Mandanten zu bestehlen.", "Richtig. Sie handelte nur bei Gelegenheit, nicht in Erfüllung oder Ausführung ihrer Aufgaben."], ["Nein, S ist nur Erfüllungs-, nicht Verrichtungsgehilfin.", "Falsch begründet. Sie ist weisungsgebunden, also beides."], ["Ja, der Unternehmer haftet immer für vorsätzliche Taten seiner Angestellten.", "Falsch („immer“)."], ["Ja, weil S den Diebstahl in den Räumen der Kanzlei begangen hat.", "Falsch. Der Ort allein genügt nicht; S handelte nur bei Gelegenheit."], ["Ja, nach § 278, weil R gegenüber M eine Obhutspflicht für den Mantel hatte.", "Falsch. § 278 setzt Handeln in Erfüllung einer Pflicht des R voraus; S handelte privat."]]}, "38": {"c": 3, "o": [["Das Abstraktionsprinzip trennt Verpflichtungsgeschäft und schuldrechtlichen Vertrag.", "Falsch. Das ist dasselbe."], ["Mit dem notariellen Kaufvertrag ist der Käufer Eigentümer der Immobilie.", "Falsch. Erst Auflassung und Eintragung."], ["§ 929 S. 1 scheidet immer aus, wenn der Kaufvertrag unwirksam ist.", "Falsch. Abstraktion."], ["Ein Kaufvertrag ist auch wirksam, wenn der Verkäufer nicht Eigentümer der Sache ist.", "Richtig. Er verpflichtet nur."], ["Die Übereignung ist unwirksam, wenn der zugrunde liegende Kaufvertrag nichtig ist.", "Falsch. Abstraktionsprinzip: Die Übereignung ist vom Kaufvertrag unabhängig."], ["Wer eine fremde Sache verkauft, macht den Kaufvertrag nach § 134 nichtig.", "Falsch. Der Verkauf einer fremden Sache ist wirksam."]]}, "39": {"c": 0, "o": [["Keiner der Verträge ist wirksam, weil Anton geschäftsunfähig ist.", "Richtig. Geschäftsunfähig, § 104 Nr. 1."], ["Der Kaufvertrag ist wirksam, weil Anton mit Taschengeld gezahlt hat.", "Falsch. § 105 I."], ["Der Kaufvertrag ist unwirksam, Anton ist aber Eigentümer geworden.", "Falsch. Auch die Einigung über die Übereignung ist nichtig."], ["Beide Geschäfte sind durch die Einwilligung wirksam.", "Falsch. Einwilligung hilft nur bei beschränkter Geschäftsfähigkeit."], ["Der Kaufvertrag ist schwebend unwirksam, bis die Eltern ihn genehmigen.", "Falsch. Erklärungen Geschäftsunfähiger sind nichtig, nicht genehmigungsfähig (§ 105 I)."], ["Nur die Übereignung des Trikots ist wirksam, weil sie Anton lediglich vorteilhaft ist.", "Falsch. Auch das gilt nur für beschränkt Geschäftsfähige (§ 107); Anton ist geschäftsunfähig."]]}, "40": {"c": 2, "o": [["… unwirksam, weil es an einem Anfechtungsgrund fehlt.", "Falsch. § 123 I."], ["… unwirksam, weil sie nicht unverzüglich erklärt wurde (§ 121).", "Falsch. § 121 gilt für §§ 119, 120."], ["… wirksam, weil die Jahresfrist ab Entdeckung gewahrt ist.", "Richtig. Frist 1 Jahr ab Entdeckung (§ 124)."], ["… schwebend unwirksam, bis V ihr zustimmt.", "Falsch. Die Anfechtung ist ein einseitiges Gestaltungsrecht."], ["… unwirksam, weil sie binnen sechs Monaten ab Vertragsschluss erfolgen muss.", "Falsch. Eine solche Frist gibt es nicht; § 124 I gibt ein Jahr ab Entdeckung."], ["… wirksam, verpflichtet K aber zum Ersatz des Vertrauensschadens (§ 122).", "Falsch. § 122 gilt nicht bei § 123."]]}, "41": {"c": 4, "o": [["Keine Ansprüche gegen B, weil der Mäher bei Gefahrübergang mangelfrei war.", "Falsch begründet. Bei digitalen Elementen zählt auch die Aktualisierungspflicht danach (§ 475b IV)."], ["Schadensersatz gegen B, weil ein technisch erzwungenes Update einen Mangel darstellt.", "Falsch. Siehe e."], ["Jedenfalls keinen Anspruch gegen den Hersteller, weil kein Vertrag besteht.", "Falsch („jedenfalls“). Deliktische Ansprüche sind denkbar."], ["Schadensersatz gegen B, gekürzt um ein Mitverschulden des H von 50 % (§ 254).", "Falsch. Die Haftung ist nach § 475b V ganz ausgeschlossen, nicht nur gekürzt."], ["Ansprüche gegen B sind ausgeschlossen, weil H die Updates nicht installiert hat.", "Richtig. § 475b V."], ["Nacherfüllung gegen B durch Lieferung eines neuen Mähers, weil das Update fehlte.", "Falsch. B hat das Update bereitgestellt; H hat es nicht installiert (§ 475b V)."]]}, "42": {"c": 4, "o": [["H kann den Vertrag über die App nach § 327c beenden, weil sie nicht bereitgestellt wurde.", "Falsch. Ware mit digitalen Elementen, §§ 327 ff. gelten nicht (§ 327a III)."], ["H hat keine Ansprüche, weil für die App kein Liefertermin vereinbart war.", "Falsch."], ["H kann sofort vom Kaufvertrag über den Mäher zurücktreten.", "Falsch. Erst nach erfolgloser Fristsetzung."], ["H muss sich wegen der App an den Softwarehersteller wenden, nicht an den Baumarkt.", "Falsch. Vertragspartner ist der Baumarkt; er schuldet auch das digitale Element (§ 475b)."], ["H kann Nacherfüllung durch Bereitstellung der App verlangen.", "Richtig. Sachmangel (§ 475b), §§ 437 Nr. 1, 439."], ["H kann nur mindern, weil der Mäher selbst mangelfrei ist und nur die App fehlt.", "Falsch. Ohne App ist der Mäher nicht nutzbar; zuerst kann H Nacherfüllung verlangen."]]}, "43": {"c": 3, "o": [["Unwirksam, die Vertretungsmacht war der Höhe nach beschränkt.", "Falsch. Die Beschränkung wirkt nach außen nicht (§ 50 I HGB)."], ["Es liegt ein unzulässiges Insichgeschäft vor, weil der Laden ihrem Bruder gehört.", "Falsch. Der Bruder ist eine andere Person, und P war befreit."], ["Die Prokura kann nur gemeinsam im Innen- und Außenverhältnis beschränkt werden.", "Falsch. Nach außen gar nicht (außer Gesamt-/Filialprokura)."], ["Alle anderen Antworten sind falsch.", "Richtig."], ["Der Kauf bindet U nur in Höhe von 225 €; den Rest schuldet P persönlich (§ 179).", "Falsch. Die interne Beschränkung wirkt nach außen nicht (§ 50 I HGB); U ist voll gebunden."], ["Der Kauf ist wirksam, weil P als Prokuristin im Innenverhältnis unbeschränkt handeln darf.", "Falsch. Im Innenverhältnis war sie auf 225 € beschränkt; nur nach außen wirkt das nicht."]]}, "44": {"c": 0, "o": [["F kann die Taxikosten von 50 € als Schadensersatz verlangen (§ 823 I, § 823 II i. V. m. § 240 StGB).", "Richtig. § 823 I und § 823 II i. V. m. § 240 StGB."], ["F kann Ersatz erst verlangen, wenn er vergeblich versucht hat, den Halter zu finden.", "Falsch. Im Einsatzfall nicht zumutbar, § 254 II ist gewahrt."], ["F darf jederzeit ein Fenster einschlagen, um das Auto wegzurollen (§ 229).", "Falsch („jederzeit“)."], ["Eine Schadensminderungspflicht des F besteht in dieser Lage nicht.", "Falsch. Sie besteht immer (§ 254 II), F hat sie nur nicht verletzt."], ["F kann die 50 € nur aus § 823 II verlangen, weil das Parken keine Eigentumsverletzung ist.", "Falsch. Das Zuparken einer Ausfahrt beeinträchtigt die Nutzung und verletzt das Eigentum (§ 823 I); daneben § 823 II."], ["F kann die 50 € nicht verlangen, weil er als Feuerwehrmann ein Dienstfahrzeug hätte rufen müssen.", "Falsch. Das war ihm nicht zumutbar; § 254 II ist gewahrt."]]}, "45": {"c": 1, "o": [["… gilt § 929 mit der Maßgabe, dass die Eintragung an die Stelle der Übergabe tritt.", "Falsch. §§ 873, 925."], ["… kann ein Formmangel des Kaufvertrages durch Auflassung und Eintragung geheilt werden.", "Richtig. § 311b I 2."], ["… ist die Auflassung erforderlich, d. h. die notarielle Beurkundung des Kaufvertrages.", "Falsch. Auflassung ist die dingliche Einigung."], ["… ist die Beurkundung des Kaufvertrages dasselbe wie die der Auflassung.", "Falsch. Zwei Geschäfte."], ["… genügt die Einigung vor dem Notar; die Eintragung ins Grundbuch ist nur deklaratorisch.", "Falsch. Die Eintragung ist konstitutiv (§ 873 I)."], ["… muss nur der Verkäufer seine Erklärung notariell abgeben, der Käufer nicht.", "Falsch. Die Auflassung erklären beide bei gleichzeitiger Anwesenheit vor dem Notar (§ 925 I)."]]}, "46": {"c": 5, "o": [["Keine Ansprüche, K ist als Fachfremder kein Erfüllungsgehilfe.", "Falsch. Es zählt nur, dass G sich seiner bedient."], ["G hat keine Ansprüche gegen K, weil er keinen Fachfremden fragen darf.", "Falsch."], ["F hat auch vertragliche Ansprüche gegen K, beide haften als Gesamtschuldner.", "Falsch. K ist nicht Vertragspartner der F."], ["F hat Ansprüche gegen G nur, wenn G den K nicht sorgfältig ausgewählt hat (§ 831).", "Falsch. Im Vertrag gilt § 278 ohne Entlastungsmöglichkeit."], ["F muss sich wegen des Bodens an K halten, weil nur K den Fehler verursacht hat.", "Falsch. Vertragspartner ist G; er haftet für K nach § 278."], ["F hat Ansprüche gegen G, der für das Verschulden des K einstehen muss.", "Richtig. § 278."]]}, "47": {"c": 2, "o": [["V kann nicht aufrechnen, weil Kaution und Schadensersatz nicht gleichartig sind.", "Falsch. Beide auf Geld gerichtet."], ["Schadensersatz setzt eine erfolglose Frist zur Reinigung voraus.", "Falsch. Schadensersatz neben der Leistung."], ["V kann Schadensersatz wegen Verletzung einer Nebenpflicht verlangen.", "Richtig. §§ 280 I, 241 II, 538."], ["Kein Anspruch, weil der vertragsgemäße Gebrauch unbestimmt war.", "Falsch. Nur die übliche Nutzung ist gedeckt."], ["V kann nur die Reinigung verlangen, nicht aber selbst reinigen und Kosten fordern.", "Falsch. Es geht um Schadensersatz neben der Leistung (§ 280 I); V kann die Kosten verlangen."], ["M haftet nicht, weil er ohne Verschulden annahm, Autoreparaturen seien erlaubt.", "Falsch. Ein Irrtum über die Reichweite des vertragsgemäßen Gebrauchs entlastet bei Fahrlässigkeit nicht (§ 276)."]]}, "48": {"c": 2, "o": [["V hat gegen L einen Anspruch auf Wiederbeschaffung eines Fahrrads.", "Falsch. L trifft kein Verschulden."], ["V hat gegen Radlglück einen Anspruch auf Lieferung eines neuen Rads.", "Falsch. Gewährleistung nach 5 Jahren verjährt."], ["L hat gegen den Hersteller Anspruch auf Ersatz der Kosten für den Konditor.", "Richtig. § 1 I ProdHaftG, Körperverletzung, Folgeschaden."], ["Keine Ansprüche, weil sich nur das allgemeine Lebensrisiko verwirklicht hat.", "Falsch."], ["L hat gegen V einen Anspruch aus § 280 I, weil V ihr ein fehlerhaftes Rad geliehen hat.", "Falsch. Der Verleiher haftet nur für Vorsatz und grobe Fahrlässigkeit (§ 599); V wusste von nichts."], ["L hat gegen den Hersteller nur einen Anspruch, wenn sie das Rad selbst gekauft hat.", "Falsch. Das ProdHaftG setzt keinen Vertrag voraus."]]}, "49": {"c": 1, "o": [["Das Testament ist unwirksam, weil es nicht notariell beurkundet ist.", "Falsch. § 2247."], ["Hanno ist kein Rechtssubjekt und kann nicht Erbe sein.", "Richtig. § 1923, § 90a."], ["Wirksam, R muss einen gesetzlichen Vertreter für Hanno benennen.", "Falsch."], ["Das Testament ist unwirksam, weil schwere Krankheit immer zur Testierunfähigkeit führt.", "Falsch („immer“)."], ["Hanno erbt, sein Erbe wird aber vom Tierheim verwaltet.", "Falsch. Ein Tier ist kein Rechtssubjekt (§ 90a)."], ["Das Testament ist wirksam, weil Tiere nach § 90a wie Personen behandelt werden.", "Falsch. § 90a sagt nur, dass Tiere keine Sachen sind; rechtsfähig sind sie nicht."]]}, "50": {"c": 4, "o": [["Auch ein Privater kann die Haftung nicht wirksam ausschließen.", "Falsch. Zwischen Privaten zulässig (§ 444)."], ["C2C kann die Haftung immer wirksam ausgeschlossen werden.", "Falsch („immer“: Arglist, Garantie)."], ["K kann den Vertrag wegen eines Eigenschaftsirrtums über den Auspuff anfechten.", "Falsch. Nach Gefahrübergang verdrängt das Mängelrecht § 119 II; zudem liegt gar kein Mangel vor."], ["Der Haftungsausschluss ist unwirksam, weil V den Rost hätte erkennen müssen.", "Falsch. Unwirksam wäre er nur bei Arglist oder Garantie (§ 444); Fahrlässigkeit genügt nicht."], ["Soweit der Auspuff ein Verschleißteil ist, liegt kein Mangel vor.", "Richtig. Übliche Beschaffenheit bei Alter und Laufleistung (§ 434 III)."], ["K kann Nacherfüllung verlangen, weil ein abfallender Auspuff stets ein Sachmangel ist.", "Falsch („stets“). Bei Alter und Laufleistung kann Verschleiß übliche Beschaffenheit sein."]]}, "51": {"c": 3, "o": [["V kann die Haftung für den Auspuff wirksam ausschließen.", "Falsch. § 476 I."], ["V hätte ohne weitere Hinweise eine negative Beschaffenheitsvereinbarung schließen können.", "Falsch. § 476 I 2 verlangt Hinweis und gesonderte Vereinbarung."], ["Angaben „ins Blaue hinein“ sind keine arglistige Täuschung.", "Falsch. Sie sind es."], ["Ein vollumfänglicher Haftungsausschluss in seinen AGB wäre unwirksam.", "Richtig. §§ 476, 309 Nr. 7."], ["V kann die Haftung ausschließen, wenn er K einen Preisnachlass gewährt.", "Falsch. Auch gegen Preisnachlass ist der Ausschluss unwirksam (§ 476 I)."], ["V kann die Verjährung für Gebrauchtwagen auf sechs Monate verkürzen.", "Falsch. Bei gebrauchten Sachen ist höchstens eine Verkürzung auf ein Jahr möglich (§ 476 II)."]]}, "52": {"c": 5, "o": [["Es ist ein Vertrag über ein digitales Produkt.", "Falsch. Ware mit digitalen Elementen."], ["K muss sich wegen der Software an den Hersteller S wenden.", "Falsch. Vertragspartner ist H."], ["H muss das e-Bike auf eigene Kosten bei K abholen.", "Falsch. Eine Abholpflicht besteht nicht zwingend."], ["K kann sofort zurücktreten, weil H die Software nicht selbst ändern kann.", "Falsch. Unvermögen des H macht die Nacherfüllung nicht unmöglich; er kann sich an S wenden. K muss zunächst eine Frist setzen."], ["K hat keine Rechte, weil das e-Bike trotz falscher Anzeige fahrbereit ist.", "Falsch. Die falsche Anzeige ist ein Mangel der Ware mit digitalen Elementen (§§ 434, 475b)."], ["K kann das e-Bike an H schicken; H muss die Kosten vorschießen.", "Richtig. §§ 439 II, 475 IV."]]}, "53": {"c": 0, "o": [["S muss das Öffnen und Verschließen der Wände samt Arbeiten bezahlen.", "Richtig. Aus- und Einbaukosten, § 439 III."], ["S muss nur neue Kabel liefern, die Wände muss R selbst öffnen lassen.", "Falsch. § 439 III."], ["S kann verlangen, dass R sich an den Kabelhersteller wendet.", "Falsch. Rückgriff ist Sache von S (§ 445a)."], ["R hat deliktische Ansprüche gegen S wegen Beschädigung seiner Villa.", "Falsch. Kein Rechtsgut über das Produkt hinaus verletzt."], ["S muss die Wandarbeiten nur bezahlen, wenn S die falschen Kabel verschuldet hat.", "Falsch. Der Ersatz der Aus- und Einbaukosten ist verschuldensunabhängig (§ 439 III)."], ["R kann sofort zurücktreten, weil das Öffnen der Wände unzumutbar ist (§ 440).", "Falsch. Unzumutbar ist das nicht; S muss die Kosten tragen, R muss Nacherfüllung zulassen."]]}, "54": {"c": 3, "o": [["Nein, weil K beschränkt geschäftsfähig ist und das Smartphone nicht wirksam annehmen kann.", "Falsch. Die Eltern haben eingewilligt (§ 107), und die Übereignung an K wäre ohnehin lediglich vorteilhaft."], ["Nein, H hat sein Angebot vor der Annahme wirksam widerrufen.", "Falsch. Das Angebot war K schon zugegangen und bindet H (§ 145). Ein Widerruf wirkt nur, wenn er vorher oder gleichzeitig zugeht (§ 130 I 2)."], ["Ja, und bei einem Prospekt im Briefkasten wäre es genauso.", "Falsch. Ein Prospekt ist nur invitatio ad offerendum."], ["Ja, ein wirksamer Kaufvertrag ist zustande gekommen, weil H an sein Angebot gebunden war.", "Richtig. Bindendes Angebot, Annahme mit Einwilligung der Eltern."], ["Nein, weil die schriftliche Zustimmung der Eltern erst bei der Annahme vorliegen durfte.", "Falsch. Eine vorherige Einwilligung (§ 107) genügt."], ["Ja, aber erst, wenn die Eltern den Vertrag nachträglich genehmigen (§ 108).", "Falsch. Die Eltern haben vorher eingewilligt; der Vertrag ist sofort wirksam."]]}, "55": {"c": 1, "o": [["A kann vom Vertrag zurücktreten, weil die Kosten unzumutbar gestiegen sind.", "Falsch. Vorrang der Anpassung (§ 313 III)."], ["A kann eine Anpassung des Vertrags verlangen, weil ihm ohne sie die Insolvenz droht (§ 313 I).", "Richtig. § 313 I, Unzumutbarkeit bei drohender Insolvenz."], ["A kann ab 2022 uneingeschränkt die aktuellen Marktpreise verlangen.", "Falsch („uneingeschränkt“)."], ["B kann wegen der staatlichen Hilfen eine Herabsetzung verlangen.", "Falsch."], ["A kann sich nicht auf § 313 berufen, weil Preissteigerungen stets Risiko des Lieferanten sind.", "Falsch („stets“). Bei drohender Insolvenz kann das Festhalten unzumutbar sein."], ["A wird nach § 275 II frei, weil die Lieferung unverhältnismäßig teuer geworden ist.", "Falsch. Wirtschaftliche Erschwerung fällt unter § 313, nicht unter § 275 II."]]}, "56": {"c": 0, "o": [["Ein „lediglich rechtlicher Vorteil“ ist rein rechtlich zu beurteilen, nicht wirtschaftlich.", "Richtig."], ["Auch bei lediglich rechtlichem Vorteil braucht der Minderjährige die Einwilligung der Eltern.", "Falsch. § 107."], ["Auch bei lediglich rechtlichem Vorteil braucht es die nachträgliche Genehmigung.", "Falsch."], ["§ 107 gilt nur für das Verpflichtungsgeschäft, nicht für die Übereignung.", "Falsch. Auch für Verfügungen."], ["Ein Geschäft ist schon dann lediglich vorteilhaft, wenn es wirtschaftlich günstig ist.", "Falsch. Maßgeblich ist allein die rechtliche Betrachtung."], ["Der Kauf zu einem Schnäppchenpreis ist für einen Minderjährigen lediglich vorteilhaft.", "Falsch. Die Pflicht zur Zahlung ist ein rechtlicher Nachteil."]]}, "57": {"c": 5, "o": [["Ja, weil die Erklärung dem Bankangestellten telefonisch zugegangen ist.", "Falsch. Formmangel."], ["Nein, weil Clara die Bürgschaft ihres Vaters hätte annehmen müssen.", "Falsch. Der Bürgschaftsvertrag wird zwischen Bürge und Gläubiger geschlossen."], ["Ja, weil der Vater aus sittlicher Pflicht für seine Tochter einstehen muss.", "Falsch."], ["Ja, weil die Bank im Vertrauen auf die Zusage ausgezahlt und damit die Form geheilt hat.", "Falsch. Heilung tritt nur ein, soweit der Bürge die Hauptschuld erfüllt (§ 766 S. 3)."], ["Ja, aber nur zur Hälfte, weil der Formfehler beiden Seiten zuzurechnen ist (§ 254).", "Falsch. Die Bürgschaft ist nichtig (§ 125); einen anteiligen Anspruch gibt es nicht."], ["Nein, die Bürgschaftserklärung hätte schriftlich erfolgen müssen.", "Richtig. §§ 766 S. 1, 125."]]}, "58": {"c": 4, "o": [["Auch bei Täuschung oder Drohung besteht ein Anspruch aus § 122.", "Falsch. § 122 nennt nur §§ 118–120."], ["Der Irrtum über eine verkehrswesentliche Eigenschaft einer Person ist ein unbeachtlicher Motivirrtum.", "Falsch. § 119 II."], ["Die Anfechtungserklärung ist nicht empfangsbedürftig, sie muss nur abgegeben werden.", "Falsch. § 143 I, Zugang nötig."], ["Der Anfechtende muss im Fall des § 122 auch den entgangenen Gewinn aus dem Vertrag ersetzen.", "Falsch. § 122 ersetzt das negative Interesse, begrenzt durch das Erfüllungsinteresse."], ["Die Schadensersatzpflicht nach § 122 setzt kein Verschulden voraus.", "Richtig."], ["Wer über den Marktwert einer Sache irrt, kann nach § 119 II anfechten.", "Falsch. Der Wert selbst ist keine Eigenschaft."]]}, "59": {"c": 2, "o": [["Nein, S hätte H zuerst eine Nachfrist setzen müssen.", "Falsch. Nacherfüllung ist unmöglich, § 326 V."], ["Nein, sie muss zuerst Nacherfüllung verlangen und abwarten.", "Falsch. Unmöglich."], ["Ja, der Rücktritt ist ohne Frist möglich (§ 326 V).", "Richtig."], ["Nein, weil H den Unfallschaden nicht kannte und kein Verschulden trifft.", "Falsch. Rücktritt ist verschuldensunabhängig."], ["Nein, weil S nur mindern kann, solange das Auto fahrbereit ist.", "Falsch. Ein schwerer Unfallschaden ist ein erheblicher Mangel; der Rücktritt ist möglich."], ["Ja, aber nur, wenn S zusätzlich wegen arglistiger Täuschung anficht.", "Falsch. H täuschte nicht arglistig, und der Rücktritt braucht keine Anfechtung."]]}, "60": {"c": 2, "o": [["Auch im stationären Handel besteht grundsätzlich ein Widerrufsrecht.", "Falsch. Nur Fernabsatz und außerhalb von Geschäftsräumen."], ["Die Widerrufsfrist beginnt immer mit dem Vertragsschluss.", "Falsch. Beim Warenkauf mit Erhalt."], ["Fehlt eine ordnungsgemäße Belehrung, beginnt die Widerrufsfrist zunächst nicht.", "Richtig. § 356 III."], ["Fällt der Fristbeginn auf einen Sonntag, beginnt sie am Montag.", "Falsch. § 193 betrifft nur das Ende."], ["Der Widerruf muss schriftlich und mit Begründung erklärt werden.", "Falsch. Er ist formfrei möglich und braucht keine Begründung (§ 355 I)."], ["Wer widerruft, muss die Kosten der Hinsendung der Ware stets selbst tragen.", "Falsch. Der Unternehmer erstattet auch die Hinsendekosten (§ 357 II)."]]}, "61": {"c": 1, "o": [["… nur mit einer notariell beurkundeten Vollmacht.", "Falsch."], ["… überhaupt nicht, weil die Erklärung höchstpersönlich ist.", "Richtig. § 1311 S. 1, höchstpersönlich."], ["… nur mit Einwilligung der Braut.", "Falsch."], ["… nur mit Einwilligung des Standesbeamten.", "Falsch."], ["… nur als Bote, der R's Erklärung wörtlich überbringt.", "Falsch. Auch eine Botenerklärung ist ausgeschlossen; die Ehegatten müssen persönlich und gleichzeitig anwesend sein (§ 1311 S. 1)."], ["… mit schriftlicher Vollmacht, weil die Eheschließung ein Vertrag ist.", "Falsch. Gerade die Eheschließung ist höchstpersönlich (§ 1311 S. 1)."]]}, "62": {"c": 5, "o": [["Die Anfechtung setzt einen unverschuldeten Irrtum voraus.", "Falsch. Auch fahrlässige Irrtümer berechtigen."], ["Schadensersatz schuldet der Anfechtende nur, wenn er den Schaden irrtümlich verursacht hat.", "Falsch."], ["Ist das positive Interesse höher als das negative, wird das positive ersetzt.", "Falsch. Umgekehrt: Das positive Interesse ist nur die Obergrenze (§ 122 I a. E.)."], ["Wer wegen arglistiger Täuschung anficht, muss den Vertrauensschaden ersetzen.", "Falsch. § 122 gilt nur für §§ 118–120."], ["Die Anfechtung wegen Irrtums muss binnen eines Jahres ab Entdeckung erklärt werden.", "Falsch. Sie muss unverzüglich erfolgen (§ 121 I)."], ["Bei einer Anfechtung nach §§ 119, 120 ist grundsätzlich das negative Interesse zu ersetzen.", "Richtig. § 122."]]}, "63": {"c": 3, "o": [["Der Kaufvertrag ist wegen der Minderjährigkeit des A schwebend unwirksam.", "Falsch. § 165."], ["Der Kaufvertrag kommt zwischen I und G nur zustande, wenn I genehmigt.", "Falsch. A hatte Vertretungsmacht."], ["Der Kaufvertrag kommt nur zustande, wenn die Eltern des A genehmigen.", "Falsch."], ["Der Kaufvertrag ist zwischen I und G zustande gekommen (§§ 164 I, 165).", "Richtig. §§ 164 I, 165."], ["Der Kaufvertrag ist zwischen A und G zustande gekommen, weil A selbst gekauft hat.", "Falsch. A hat im Namen des I gehandelt („die Rechnung geht an I“)."], ["I kann den Vertrag widerrufen, weil er es sich anders überlegt hat.", "Falsch. Ein solches Widerrufsrecht gibt es nicht."]]}, "64": {"c": 0, "o": [["N konnte wirksam 1.000 € abheben, muss aber alles der Tante geben.", "Richtig. § 667."], ["N hat beim Abheben der zweiten 500 € ohne Vertretungsmacht gehandelt.", "Falsch. Im Außenverhältnis unbeschränkt."], ["Die Bank durfte N nicht 1.000 € auszahlen und haftet T dafür.", "Falsch."], ["T hat für die zweiten 500 € keine Anspruchsgrundlage gegen N.", "Falsch. § 667, § 280."], ["T kann die 500 € nur von der Bank zurückverlangen, nicht von N.", "Falsch. Die Bank hat wirksam an den Bevollmächtigten gezahlt; T hält sich an N (§ 667)."], ["Die Abhebung ist schwebend unwirksam, bis T sie genehmigt (§ 177).", "Falsch. N hatte im Außenverhältnis unbeschränkte Vollmacht."]]}, "65": {"c": 4, "o": [["Weil nichts zur Beschaffenheit vereinbart war, liegt keine Beschaffenheitsabweichung vor.", "Falsch. Objektive Anforderungen."], ["Es ist nicht davon auszugehen, dass der Mangel schon bei Gefahrübergang vorlag.", "Falsch. § 477."], ["Wegen Konkretisierung schuldet F beim Standardgewehr keine Neulieferung.", "Falsch. Konkretisierung schützt nicht vor Gewährleistung."], ["B muss beweisen, dass das Visier schon bei Übergabe defekt war.", "Falsch. Beim Verbrauchsgüterkauf hilft § 477; unabhängig davon ist der Mangel hier offensichtlich."], ["Ein Mangel liegt auch vor, wenn die Sache sich nicht für die gewöhnliche Verwendung eignet.", "Richtig. § 434 III."], ["Beim Sondermodell scheidet jede Nacherfüllung aus, weil es eine Stückschuld ist.", "Falsch. Eine Reparatur ist auch bei Stückschulden möglich."]]}, "66": {"c": 1, "o": [["B hat beim Sondermodell keinen Anspruch auf Mangelbeseitigung.", "Falsch."], ["F ist von der Nacherfüllung befreit, wenn die Reparatur nicht möglich ist.", "Richtig. Stückschuld, Neulieferung kommt bei der Sonderanfertigung nicht in Betracht (§ 275 I)."], ["B muss beweisen, dass der Mangel schon bei Übergabe bestand.", "Falsch. § 477."], ["F ist in keinem Fall schadensersatzpflichtig.", "Falsch. Pauschal nicht feststellbar."], ["F muss beim Sondermodell ein neues Gewehr anfertigen, wenn die Reparatur scheitert.", "Falsch. Bei der Sonderanfertigung (Stückschuld) scheidet Neulieferung aus (§ 275 I)."], ["B kann beim Sondermodell sofort zurücktreten, weil Sonderanfertigungen nicht repariert werden.", "Falsch. Zuerst kann F reparieren; erst wenn das scheitert, kommt der Rücktritt in Betracht."]]}, "67": {"c": 0, "o": [["O kann die 15.000 € von C zurückverlangen, weil die Leistung unmöglich wurde.", "Richtig. §§ 326 I, IV, 346."], ["Mit Verstreichen der Leistungszeit wurde die Leistung des C nicht unmöglich.", "Falsch. Absolutes Fixgeschäft."], ["O kann von C die vollen 16.000 € für das Ersatzcatering verlangen.", "Falsch. Schaden ist nur die Differenz von 1.000 €."], ["Für das Zelt hat O keinen Anspruch, weil kein Schaden entstanden ist.", "Falsch. Aufwendungsersatz § 284."], ["O kann nur zurücktreten, wenn er C zuvor eine Nachfrist gesetzt hat.", "Falsch. Beim absoluten Fixgeschäft ist die Leistung unmöglich; eine Frist ist sinnlos."], ["O kann die 15.000 € nur verlangen, wenn C die Verspätung verschuldet hat.", "Falsch. Die Rückforderung nach § 326 IV ist verschuldensunabhängig."]]}, "68": {"c": 3, "o": [["Hat der Sender die Verzögerung verschuldet, muss C die 15.000 € nicht zurückzahlen.", "Falsch. Die Rückzahlung ist verschuldensunabhängig, und das Risiko liegt in C’s Sphäre."], ["O kann von Zeltverleiher Z die 2.000 € zurückverlangen.", "Falsch. Z hat ordnungsgemäß geleistet."], ["Bei einem unverschuldeten Unfall des C muss er die 15.000 € nicht zurückzahlen.", "Falsch. § 326 I, IV gelten ohne Verschulden."], ["Bei einem unverschuldeten Unfall des C bekommt O die 2.000 € für das Zelt nicht.", "Richtig. § 284 setzt Vertretenmüssen voraus."], ["O kann die 2.000 € für das Zelt in jedem Fall verlangen, weil sie vergeblich waren.", "Falsch. § 284 setzt die Voraussetzungen des Schadensersatzes statt der Leistung voraus, also Vertretenmüssen."], ["C kann gegen die Rückzahlung mit seinen Kosten für die Zutaten aufrechnen.", "Falsch. C hat keinen Gegenanspruch; die Zutaten sind sein Risiko."]]}, "69": {"c": 2, "o": [["P muss auch bei grober Fahrlässigkeit nicht für den Schaden geradestehen.", "Falsch. § 823 I."], ["P ist Verrichtungs-, aber kein Erfüllungsgehilfe des M.", "Falsch. Er ist beides."], ["M muss für das Handeln des P wie für eigenes Verschulden einstehen (§ 278).", "Richtig. §§ 280 I, 278."], ["M ist frei, weil er die Reifen nicht selbst gewechselt hat.", "Falsch."], ["M haftet nur, wenn er P nicht sorgfältig ausgewählt hat; er kann sich entlasten.", "Falsch. Im Vertrag gilt § 278 ohne Entlastungsmöglichkeit."], ["Anton muss sich an P halten, weil nur P einen Fehler gemacht hat.", "Falsch. Vertragspartner ist M; er haftet für P (§ 278). P haftet daneben aus § 823 I."]]}, "70": {"c": 4, "o": [["Vitus und Katharina haben eine Schickschuld vereinbart.", "Falsch. Er schuldet mehr als die Übergabe an einen Transporteur."], ["Bei der Bringschuld fallen Leistungs- und Erfolgsort auseinander.", "Falsch. Das ist die Schickschuld."], ["Die Bringschuld erkennt man daran, dass der Verkäufer die Versandkosten trägt.", "Falsch. § 269 III."], ["Sie haben eine Holschuld vereinbart, weil im Zweifel am Wohnsitz des Schuldners zu leisten ist.", "Falsch. § 269 I gilt nur im Zweifel; hier folgt aus dem Einbau die Bringschuld."], ["Vitus und Katharina haben eine Bringschuld vereinbart, weil Vitus in der Wohnung einbauen soll.", "Richtig. Der Einbau beim Gläubiger ist starkes Indiz."], ["Bei der Bringschuld geht die Gefahr schon mit Absendung der Küche über.", "Falsch. Bei der Bringschuld erst mit Übergabe beim Gläubiger."]]}, "71": {"c": 5, "o": [["Über die c.i.c. bekommt S das positive Interesse ersetzt.", "Falsch. Negatives Interesse."], ["Nach §§ 280 ff. wird allgemein der Vertrauensschaden ersetzt.", "Falsch. Grundsätzlich das Erfüllungsinteresse."], ["Ohne Vertretenmüssen ist Schadensersatz generell ausgeschlossen.", "Falsch. Gefährdungshaftung."], ["S bekommt die 5.600 € voll, weil der Verzug schon am 2.1. ohne Mahnung eintrat.", "Falsch. Der Verzug trat zwar ein, aber S hätte den Schaden mindern können (§ 254 II)."], ["S bekommt nichts, weil er erst am 1.8. eine Frist gesetzt hat.", "Falsch. Für den Verzögerungsschaden braucht es keine Frist, nur Verzug."], ["S bekommt den geltend gemachten Schadensersatz nicht in voller Höhe.", "Richtig. § 254 II, er hätte den Schaden durch früheres Handeln oder anderen Einsatz mindern können."]]}, "72": {"c": 1, "o": [["Zirno muss Paul eine andere, gleichwertige Stute anbieten.", "Falsch. Stückschuld, und Paul ist im Annahmeverzug."], ["Paul muss die Stute trotzdem bezahlen, weil er im Annahmeverzug war.", "Richtig. Annahmeverzug, Zirno haftet nur für Vorsatz und grobe Fahrlässigkeit (§ 300 I), § 326 II."], ["Weil Paul den Stall unverschuldet nicht fertig hatte, ging die Gefahr nicht über.", "Falsch. Annahmeverzug ist verschuldensunabhängig."], ["Hätte Zirno schon am 14.1. angeboten, müsste Paul ebenfalls zahlen.", "Falsch. Ein verfrühtes Angebot begründet keinen Annahmeverzug, die Vereinbarung geht § 271 II vor."], ["Paul muss nicht zahlen, weil Zirno leicht fahrlässig gehandelt hat.", "Falsch. Im Annahmeverzug haftet Zirno nur für Vorsatz und grobe Fahrlässigkeit (§ 300 I)."], ["Paul muss zahlen, kann aber Schadensersatz für die Stute verlangen.", "Falsch. Zirno hat den Untergang im Annahmeverzug nicht zu vertreten."]]}, "73": {"c": 3, "o": [["Wer die Sache nicht mehr besitzt, ist von der Herausgabe stets befreit.", "Falsch. §§ 816, 818 II."], ["Ohne Verschulden des Bereicherten besteht kein Anspruch.", "Falsch. Verschuldensunabhängig."], ["Der Anspruch ist nicht ausgeschlossen, wenn der Leistende seine Nichtschuld kannte.", "Falsch. § 814."], ["Wer ohne Rechtsgrund eine Sache erlangt, muss auch den Ersatz für ihre Zerstörung herausgeben.", "Richtig. § 818 I (Surrogat)."], ["Der Bereicherte muss stets den objektiven Wert ersetzen, auch wenn er entreichert ist.", "Falsch. Der gutgläubige Bereicherte kann sich auf § 818 III berufen."], ["Ein Anspruch aus § 812 setzt voraus, dass der Leistende den Vertrag angefochten hat.", "Falsch. Es genügt das Fehlen eines Rechtsgrundes, aus welchem Grund auch immer."]]}, "74": {"c": 2, "o": [["Victor haftet nicht aus Gewährleistung, weil er von der Manipulation nichts wusste.", "Falsch. Gewährleistung ist verschuldensunabhängig."], ["Karl hat einen Schadensersatzanspruch gegen Victor.", "Falsch. Victor hat nichts zu vertreten, der Hersteller ist nicht sein Erfüllungsgehilfe."], ["Karl kann von Victor Beseitigung des Mangels verlangen, soweit sie möglich ist.", "Richtig. §§ 437 Nr. 1, 439, 275."], ["Karl hat einen Nachbesserungsanspruch gegen VW als Hersteller.", "Falsch. Kein Kaufvertrag mit VW."], ["Karl kann ohne Fristsetzung zurücktreten, weil der Mangel vom Hersteller stammt.", "Falsch. Auch dann gilt der Vorrang der Nacherfüllung beim Verkäufer."], ["Victor kann die Nacherfüllung verweigern, weil der Hersteller kein Erfüllungsgehilfe ist.", "Falsch. Die Nacherfüllung ist verschuldensunabhängig; § 278 spielt dafür keine Rolle."]]}, "75": {"c": 4, "o": [["Katja kann den Kaufvertrag wegen eines Irrtums über die Kratzer anfechten.", "Falsch. Es gibt keinen Vertrag."], ["Katja hat wegen der Kratzer einen Anspruch auf Nacherfüllung.", "Falsch."], ["Katja kann den Kaufpreis wegen der Kratzer auf 100 € mindern.", "Falsch."], ["Ein Kaufvertrag über 150 € ist durch Katjas Anfrage zustande gekommen.", "Falsch. Das Inserat war nur eine invitatio ad offerendum; die Anfrage ist keine Annahme."], ["Ein Kaufvertrag ist mangels Einigung über den Preis nicht zustande gekommen.", "Richtig. Inserat invitatio, Katjas Angebot über 100 € wurde abgelehnt."], ["Ein Kaufvertrag über 100 € ist zustande gekommen, weil Victoria das Inserat gestellt hat.", "Falsch. Victoria hat Katjas Angebot über 100 € abgelehnt."]]}, "76": {"c": 0, "o": [["Kurt kann von der Händlerin Nachbesserung verlangen.", "Richtig. Mangel bei Gefahrübergang (Übergabe), § 439."], ["Kurt hat Gewährleistungsrechte nur, wenn er der Händlerin Verschulden nachweist.", "Falsch."], ["Kurt kann sofort den Kaufpreis mindern.", "Falsch. Vorrang der Nacherfüllung."], ["Victoria kann die Nachbesserung unter keinen Umständen ablehnen.", "Falsch. § 439 IV."], ["Kurt hat keine Rechte, weil der Marder den Schaden verursacht hat und niemand haftet.", "Falsch. Der Schaden entstand vor Gefahrübergang; das Fahrzeug war bei Übergabe mangelhaft."], ["Kurt muss sich wegen des Marderschadens an seine eigene Versicherung halten.", "Falsch. Er hat Mängelrechte gegen die Händlerin."]]}, "77": {"c": 5, "o": [["Kassandra hatte beim Heben der Hand keinen Rechtsbindungswillen.", "Falsch. Sie wollte bieten."], ["Die Anfechtung ist ausgeschlossen, weil der Vertrag verbindlich ist.", "Falsch. Gerade verbindliche Verträge werden angefochten."], ["Kassandra muss die 120 € zahlen.", "Falsch. Sie könnte anfechten."], ["Kassandra kann anfechten und die Uhr dann trotzdem für 110 € ablehnen.", "Falsch. Wer anficht, muss sich am Gewollten festhalten lassen, wenn der andere es anbietet."], ["Kassandra kann anfechten, muss aber 120 € als Vertrauensschaden zahlen (§ 122).", "Falsch. § 122 ersetzt nicht den Kaufpreis."], ["Kassandra muss die Uhr für 110 € abnehmen (§ 242).", "Richtig. Wer anficht, muss sich am Gewollten festhalten lassen."]]}, "78": {"c": 5, "o": [["Durch Emils Verhalten ist ein Rechtsgeschäft mit Martina entstanden.", "Falsch."], ["Emil haftet selbst für die Parfumflasche.", "Falsch. § 828 I."], ["Emil haftet nur, wenn er die nötige Einsichtsfähigkeit hatte.", "Falsch. Das gilt erst ab 7 (§ 828 III)."], ["Martina haftet wegen des Schildes „Eltern haften für ihre Kinder“ in jedem Fall.", "Falsch. Das Schild ändert die Rechtslage nicht."], ["Martina haftet nicht, weil nur Eltern, nicht Großeltern aufsichtspflichtig sein können.", "Falsch. Aufsichtspflichtig kann auch sein, wer die Aufsicht vertraglich oder tatsächlich übernommen hat (§ 832)."], ["Martina haftet nur, wenn sie ihre Aufsichtspflicht verletzt hat.", "Richtig. § 832, das Schild ändert nichts."]]}, "79": {"c": 3, "o": [["Ludwig haftet wegen der Wirkung nur zwischen den Vertragsparteien nicht.", "Falsch. Es geht um Kristins eigenen Schaden."], ["Die Vertragsstrafe ist ein behebbarer Schaden nach §§ 280 I, III, 281.", "Falsch. Die spätere Lieferung beseitigt ihn nicht."], ["Nicht behebbare Schäden brauchen eine Frist zur Nacherfüllung.", "Falsch."], ["Die Vertragsstrafe ist ein Verzögerungsschaden (§§ 280 I, II, 286).", "Richtig. Verzögerungsschaden."], ["Kristin bekommt die Vertragsstrafe nur, wenn Ludwig sie im Vertrag übernommen hat.", "Falsch. Ein eigenes Versprechen ist nicht nötig; es geht um Verzögerungsschaden."], ["Kristin muss die Schrauben zurückweisen, um die Vertragsstrafe ersetzt zu bekommen.", "Falsch. Der Verzögerungsschaden wird neben der Leistung ersetzt."]]}, "80": {"c": 4, "o": [["Bei einer Gattungsschuld ist Unmöglichkeit grundsätzlich ausgeschlossen.", "Falsch. Wenn die ganze Gattung untergeht oder nach Konkretisierung."], ["Bei anfänglicher Unmöglichkeit kommt kein wirksamer Vertrag zustande.", "Falsch. § 311a I."], ["Bei nachträglicher Unmöglichkeit wird der Schuldner nur frei, wenn er sie nicht zu vertreten hat.", "Falsch. Befreiung immer, Vertretenmüssen spielt nur für Schadensersatz eine Rolle."], ["Bei Unmöglichkeit entfällt die Gegenleistung nur, wenn der Gläubiger zurücktritt.", "Falsch. § 326 I 1 wirkt kraft Gesetzes."], ["§ 275 erfasst anfängliche und nachträgliche, subjektive und objektive Unmöglichkeit.", "Richtig."], ["Ist die Leistung nur für den Schuldner unmöglich, bleibt er stets zur Leistung verpflichtet.", "Falsch. § 275 I erfasst auch das subjektive Unvermögen."]]}};
const SR={"1": {"c": 4, "o": [["Zwei Unternehmer einen Kaufvertrag über eine bewegliche Sache schließen.", "Falsch. Das ist ein B2B-Kauf, unter Kaufleuten ein Handelskauf (§§ 343, 377 HGB). Es fehlt der Verbraucher als Käufer."], ["Zwei Verbraucher einen Kaufvertrag über eine bewegliche Sache schließen.", "Falsch. Das ist ein Privatkauf (C2C). Es fehlt der Unternehmer als Verkäufer, deshalb gelten nur die §§ 433 ff. ohne die §§ 474 ff."], ["Ein Verbraucher als Verkäufer einem Unternehmer eine bewegliche Sache verkauft.", "Falsch. Das ist die umgekehrte Rollenverteilung, z. B. beim Verkauf des Gebrauchtwagens an einen Händler. § 474 schützt nur den Verbraucher als Käufer."], ["Ein Unternehmer einem Verbraucher ein Grundstück verkauft.", "Falsch. § 474 I erfasst nur Waren, also bewegliche Sachen."], ["Ein Unternehmer als Verkäufer einem Verbraucher eine bewegliche Sache verkauft.", "Richtig. Das ist exakt die Definition des § 474 I 1: Unternehmer (§ 14) verkauft an Verbraucher (§ 13) eine Ware. Kurz: „b (VK) an c (K)“."], ["Ein Unternehmer einem Verbraucher eine Sache im Ladengeschäft und nicht online verkauft.", "Falsch. Der Vertriebsweg spielt keine Rolle; Verbrauchsgüterkauf liegt online wie im Laden vor."]]}, "2": {"c": 1, "o": [["Das Abstraktionsprinzip trennt das Verpflichtungsgeschäft vom schuldrechtlichen Vertrag.", "Falsch. Das ist ein Wortspiel: Verpflichtungsgeschäft und schuldrechtlicher Vertrag sind dasselbe. Getrennt werden Verpflichtungsgeschäft und Verfügungsgeschäft (dinglicher Vertrag)."], ["Ein Kaufvertrag ist auch wirksam, wenn der Verkäufer nicht Eigentümer der Sache ist.", "Richtig. Der Kaufvertrag begründet nur die Pflicht, Eigentum zu verschaffen. Ob der Verkäufer das kann, ist eine Frage der Erfüllung und nicht der Wirksamkeit des Kaufvertrags. Schafft er es nicht, haftet er wegen Rechtsmangels (§§ 435, 437) oder wegen Unmöglichkeit (§§ 275, 311a)."], ["Mit dem notariellen Kaufvertrag über eine Immobilie wird der Käufer Eigentümer.", "Falsch. Der notarielle Kaufvertrag ist nur das Verpflichtungsgeschäft (§ 311b I). Eigentum entsteht erst durch Auflassung und Eintragung (§§ 873, 925)."], ["Ein Eigentumserwerb nach § 929 S. 1 scheidet immer aus, wenn der Kaufvertrag unwirksam ist.", "Falsch. Nach dem Abstraktionsprinzip ist die Übereignung unabhängig vom Kaufvertrag wirksam. Das Wort „immer“ ist das Warnsignal, es gibt allenfalls Ausnahmen bei Fehleridentität. Der Ausgleich erfolgt über § 812."], ["Wer eine fremde Sache verkauft, macht den Kaufvertrag nach § 134 nichtig.", "Falsch. Ein Verbotsgesetz gibt es dafür nicht; der Vertrag ist wirksam."], ["Die Übereignung einer beweglichen Sache bedarf der notariellen Form.", "Falsch. § 929 S. 1 verlangt nur Einigung und Übergabe."]]}, "3": {"c": 0, "o": [["K ist Eigentümer des Rechners geworden, obwohl kein Kaufvertrag besteht.", "Richtig. Für § 929 S. 1 braucht es Einigung über den Eigentumsübergang und Übergabe. V überreicht das Gerät, damit K es zu eigen hat, und K nimmt es entgegen: Beide sind sich einig, dass K Eigentümer wird. V ist Eigentümer und damit berechtigt. Dass der Kaufvertrag am Preis scheitert, ist wegen des Abstraktionsprinzips unerheblich."], ["V und K haben einen Kaufvertrag mit einem Kaufpreis von 350 € geschlossen.", "Falsch. K hat das 350-€-Angebot nicht angenommen, sondern mit „300 €“ abgeändert. Das ist nach § 150 II eine Ablehnung verbunden mit einem neuen Angebot. Das ursprüngliche Angebot ist erloschen (§ 146)."], ["V und K haben sich durch die Übergabe auf einen Kaufpreis von 300 € geeinigt.", "Falsch. V hat das 300-€-Angebot nie angenommen, er wusste nichts davon. Seine Erklärung bei der Übergabe bezog sich erkennbar auf seine eigenen 350 €. Es liegt ein versteckter Dissens über den Preis vor (§ 155), und weil der Preis ein essentiale negotii ist, kommt kein Kaufvertrag zustande."], ["K ist noch nicht Eigentümer des Rechners geworden, weil eine Einigung noch aussteht.", "Falsch. Es fehlt nur die schuldrechtliche Einigung (Kaufvertrag). Die dingliche Einigung, dass das Eigentum übergehen soll, liegt vor."], ["Ein Kaufvertrag über 300 € besteht, weil K's WhatsApp V's Machtbereich erreicht hat.", "Falsch. Selbst bei Zugang hätte V das neue Angebot nie angenommen; seine Erklärung bezog sich auf 350 €."], ["K ist nicht Eigentümer, weil die Übereignung wegen des Dissenses ebenfalls unwirksam ist.", "Falsch. Abstraktionsprinzip: Die dingliche Einigung liegt vor und ist vom Kaufvertrag unabhängig."]]}, "4": {"c": 5, "o": [["K muss nichts an V herausgeben, weil er Eigentümer geworden ist.", "Falsch. Ohne Rechtsgrund darf K die Bereicherung nicht behalten."], ["K muss den Rechner herausgeben und einen etwaigen Aufwendungsersatz leisten.", "Falsch. Einen Aufwendungsersatz schuldet K nicht. Herauszugeben sind nur das Erlangte und gezogene Nutzungen (§ 818 I). Eher kann K umgekehrt eigene Verwendungen gegenrechnen."], ["K muss dem V die 350 € aus dem Kaufvertrag bezahlen.", "Falsch. Ein Kaufpreisanspruch aus § 433 II setzt einen wirksamen Kaufvertrag voraus. Der fehlt (Dissens)."], ["K muss den Rechner nach § 985 herausgeben, weil V Eigentümer geblieben ist.", "Falsch. K ist Eigentümer geworden (Abstraktionsprinzip); V hat nur den Bereicherungsanspruch."], ["K muss 300 € zahlen, weil er damit einverstanden war.", "Falsch. Ein Kaufvertrag über 300 € ist nicht zustande gekommen."], ["K muss den Rechner an V herausgeben, wenn V das verlangt (§ 812).", "Richtig. K hat Eigentum und Besitz am Rechner durch Leistung des V erlangt, ohne rechtlichen Grund, weil kein Kaufvertrag besteht. Nach § 812 I 1 Alt. 1 muss er das Erlangte herausgeben, also den Rechner zurückübereignen und zurückgeben."]]}, "5": {"c": 3, "o": [["Das Bereitstellen des Wassers in der Minibar ist eine invitatio ad offerendum des V.", "Falsch. Eine invitatio liegt vor, wenn der Anbieter sich wegen begrenzten Vorrats oder unklarer Bonität nicht binden will. Bei der Minibar weiß V genau, wer im Zimmer ist und dass der Vorrat für diesen Gast bestimmt ist. Es liegt ein verbindliches Angebot vor."], ["Das Bereitstellen des Wassers ist eine Annahme des V auf ein Angebot der K.", "Falsch. Die Reihenfolge ist vertauscht. Das Bereitstellen kommt zeitlich vor jeder Erklärung der K und ist deshalb das Angebot."], ["Die Annahme der K ist nicht wirksam, weil sie V nicht zugegangen ist.", "Falsch. Das ist genau der Fall des § 151 S. 1, der Zugang ist entbehrlich."], ["Der Zugang der Annahmeerklärung der K ist nach der Verkehrssitte entbehrlich (§ 151 S. 1).", "Richtig. K nimmt durch Trinken an, also durch Betätigung des Annahmewillens. Nach § 151 S. 1 ist der Zugang dieser Annahme entbehrlich, weil V als Hotelier nach der Verkehrssitte keine Erklärung des Gastes um Mitternacht erwartet."], ["K muss nicht zahlen, weil sie nur ein Glas und nicht die ganze Flasche getrunken hat.", "Falsch. Mit dem Öffnen und Trinken hat sie das Angebot für die Flasche angenommen."], ["Ein Vertrag kam erst bei der Abreise zustande, als V die 4,50 € verlangte.", "Falsch. Der Vertrag kam schon mit dem Trinken zustande (§ 151 S. 1)."]]}, "6": {"c": 2, "o": [["Ja, weil F das Buch nicht innerhalb der 14 Tage zurückgesandt hat.", "Falsch. Der Verlag kann einseitig nicht bestimmen, dass Untätigkeit als Annahme gilt. Schweigen ist keine Willenserklärung. Außerdem greift § 241a I."], ["Ja, weil F seine Ablehnung dem Verlag nicht mitgeteilt hat.", "Falsch. Es gibt keine Pflicht, unbestellte Angebote abzulehnen."], ["Nein, selbst dann nicht, wenn F das Buch seinem Opa geschenkt hat.", "Richtig. Nach § 241a I wird durch die Lieferung unbestellter Waren durch einen Unternehmer an einen Verbraucher kein Anspruch gegen den Verbraucher begründet. Das gilt nach herrschender Meinung auch dann, wenn er die Sache nutzt oder weiterverschenkt. Selbst ein Verschenken ist hier nicht als konkludente Annahme zu werten, denn § 241a soll gerade verhindern, dass der Verbraucher durch Umgang mit der Ware in einen Vertrag gerät."], ["Nein, aber nur, weil F den Kaufvertrag wegen Irrtums anfechten kann.", "Falsch. Das Ergebnis „Nein“ stimmt, die Begründung nicht: Es gibt gar keinen Vertrag, den man anfechten könnte."], ["Ja, weil F das Buch gelesen und damit konkludent angenommen hat.", "Falsch. § 241a I schließt Ansprüche auch bei Nutzung aus."], ["Nein, F muss das Buch aber auf eigene Kosten zurückschicken.", "Falsch. Auch eine Rücksendepflicht besteht nicht (§ 241a I)."]]}, "7": {"c": 4, "o": [["Nein, weil die Schenkung kein zweiseitiges Rechtsgeschäft ist.", "Falsch. Das Ergebnis stimmt, die Begründung nicht. Die Schenkung ist ein Vertrag, also ein zweiseitiges Rechtsgeschäft. Sie ist nur einseitig verpflichtend."], ["Ja, weil ein wirksamer Schenkungsvertrag geschlossen wurde.", "Falsch. Das Schenkungsversprechen ist formnichtig (§§ 518 I, 125 S. 1)."], ["Ja, weil das Versprechen einer sittlichen Pflicht entspricht.", "Falsch. Eine sittliche Pflicht ersetzt nicht die Form. § 534 betrifft nur Ausnahmen bei Rückforderung und Widerruf von Pflicht- und Anstandsschenkungen."], ["Ja, weil die Enkelin die Bedingung erfüllt hat und das Versprechen dadurch bindend wurde.", "Falsch. Die Bedingung ändert nichts an der Formbedürftigkeit (§ 518 I)."], ["Nein, weil das Schenkungsversprechen notariell zu beurkunden war.", "Richtig. § 518 I 1 verlangt die notarielle Beurkundung des Versprechens. Ohne sie ist es nichtig (§ 125 S. 1). Eine Heilung nach § 518 II ist nicht eingetreten, weil noch nicht geleistet wurde."], ["Ja, weil eine Auslobung vorliegt, die formfrei ist (§ 657).", "Falsch. Eine Auslobung richtet sich an die Öffentlichkeit, nicht an eine bestimmte Person."]]}, "8": {"c": 0, "o": [["Nein, weil der Formmangel durch die Übergabe des Geldes geheilt wurde (§ 518 II).", "Richtig. Mit der Übergabe des Geldes ist die versprochene Leistung bewirkt, und der Mangel der Form wird geheilt (§ 518 II). Die Schenkung ist der Rechtsgrund für die Zahlung, also scheidet § 812 aus. Auch ein Widerruf nach § 530 scheitert, weil die Einladung des Freundes kein grober Undank gegenüber der Großmutter ist. Ebenso tragbar ist die Lösung als Handschenkung: Sie ist ohnehin formfrei."], ["Ja, weil das Versprechen formunwirksam war und die 500 € ohne Rechtsgrund geleistet wurden.", "Falsch. Der Formmangel ist durch die Bewirkung der Leistung geheilt (§ 518 II). Damit besteht ein Rechtsgrund."], ["Ja, weil der Formmangel wegen der Warnfunktion nicht geheilt werden kann.", "Falsch. Gerade weil die Warnfunktion mit der tatsächlichen Leistung erfüllt ist (die Großmutter spürt das Opfer), lässt § 518 II die Heilung zu."], ["Ja, weil die Großmutter ihre einseitige Verpflichtung jederzeit widerrufen kann.", "Falsch. „Einseitig verpflichtend“ heißt nicht „frei widerruflich“. Ein Widerruf ist nur unter den engen Voraussetzungen der §§ 530 ff. möglich."], ["Ja, weil die Einladung des ungeliebten Freundes grober Undank ist (§ 530).", "Falsch. Das ist keine schwere Verfehlung gegenüber der Großmutter."], ["Nein, aber nur, weil die Rückforderung einer Schenkung nach § 814 ausgeschlossen ist.", "Falsch. § 814 passt nicht; die Schenkung ist schlicht wirksamer Rechtsgrund."]]}, "9": {"c": 3, "o": [["Die WE ab dem Zeitpunkt der Anfechtungserklärung nichtig ist.", "Falsch. Das wäre eine Wirkung ex nunc (wie bei der Kündigung). § 142 I ordnet die Nichtigkeit von Anfang an an."], ["Die WE nur nichtig wird, wenn der Anfechtende den Irrtum nicht verschuldet hat.", "Falsch. Verschulden spielt keine Rolle. Auch wer sich fahrlässig irrt, kann anfechten. Er haftet dann aber verschuldensunabhängig nach § 122."], ["Auch der Vertragspartner seine eigene WE anfechten kann.", "Falsch. Das Anfechtungsrecht steht nur dem zu, der sich geirrt hat oder getäuscht wurde. Mit der Nichtigkeit der einen WE fällt der Vertrag ohnehin, eine Anfechtung des Gegners ist überflüssig."], ["Die WE rückwirkend, also von Anfang an nichtig ist.", "Richtig. § 142 I: „ist als von Anfang an nichtig anzusehen“ (ex tunc)."], ["Der Vertrag mit geändertem Inhalt bestehen bleibt, so wie der Anfechtende ihn wollte.", "Falsch. Die Anfechtung vernichtet, sie gestaltet den Vertrag nicht um."], ["Die WE erst nichtig wird, wenn der Gegner der Anfechtung zustimmt.", "Falsch. Die Anfechtung ist ein einseitiges Gestaltungsrecht."]]}, "10": {"c": 5, "o": [["M kann den Kaufvertrag anfechten, weil sie sich über Maiks Vorlieben geirrt hat.", "Falsch. Das ist ein reiner Motivirrtum: M wusste genau, was sie kaufte, sie irrte nur über ihre Beweggründe. Er ist unbeachtlich. Eine Täuschung durch G liegt nicht vor."], ["M kann vom Vertrag mit G zurücktreten, muss vorher dem G aber eine Frist setzen.", "Falsch. Ein Rücktritt nach §§ 437 Nr. 2, 323 setzt einen Mangel voraus. Die Figuren sind mangelfrei, sie gefallen nur nicht."], ["M kann binnen 14 Tagen ab Vertragsschluss widerrufen.", "Falsch. Ein Widerrufsrecht besteht nur bei Fernabsatz- oder Außergeschäftsraumverträgen (§ 312g I). M hat im Einkaufszentrum, also im Geschäftslokal des G, gekauft."], ["M kann vom Vertrag zurücktreten, weil die Geschäftsgrundlage weggefallen ist (§ 313).", "Falsch. Das Verwendungsrisiko trägt der Käufer allein."], ["M kann die Figuren umtauschen, weil Händler gesetzlich zum Umtausch verpflichtet sind.", "Falsch. Ein gesetzliches Umtauschrecht gibt es nicht; nur Kulanz."], ["M hat gegenüber G insoweit keine Rechte, sondern ist auf seine Kulanz angewiesen.", "Richtig. Weder Anfechtung noch Rücktritt noch Widerruf greifen. M bleibt nur die Bitte um Kulanz."]]}, "11": {"c": 1, "o": [["Auch bei Anfechtung wegen Täuschung oder Drohung besteht ein Anspruch aus § 122.", "Falsch. § 122 I nennt ausdrücklich nur die Anfechtung nach §§ 119, 120. Es wäre absurd, wenn der Getäuschte dem Täuschenden Schadensersatz schulden würde."], ["Die Schadensersatzpflicht nach § 122 setzt kein Verschulden des Erklärenden voraus.", "Richtig. § 122 ist eine verschuldensunabhängige Vertrauenshaftung (Veranlassungsprinzip). Der Erklärende hat den Rechtsschein gesetzt und muss den Vertrauensschaden ersetzen, auch wenn ihn kein Vorwurf trifft."], ["Der Irrtum über eine verkehrswesentliche Eigenschaft einer Person ist ein unbeachtlicher Motivirrtum.", "Falsch. § 119 II nennt ausdrücklich Eigenschaften „der Person oder der Sache“. Das ist der gesetzlich anerkannte, ausnahmsweise beachtliche Motivirrtum."], ["Die Anfechtungserklärung ist nicht empfangsbedürftig und muss nicht zugehen.", "Falsch. Sie ist einseitig, aber empfangsbedürftig, denn sie erfolgt „gegenüber dem Anfechtungsgegner“ (§ 143 I). Sie muss zugehen."], ["§ 122 ersetzt das Erfüllungsinteresse, also den Gewinn aus dem Vertrag.", "Falsch. Ersetzt wird das negative Interesse, begrenzt durch das Erfüllungsinteresse."], ["Die Anfechtung wegen Irrtums ist binnen eines Jahres ab Kenntnis des Irrtums zu erklären.", "Falsch. Sie muss unverzüglich erfolgen (§ 121 I)."]]}, "12": {"c": 2, "o": [["unwirksam, weil kein Anfechtungsgrund vorliegt.", "Falsch. Eine bewusste Lüge über die Unfallfreiheit auf ausdrückliche Nachfrage ist der Paradefall der arglistigen Täuschung."], ["unwirksam, weil sie nicht unverzüglich nach Entdeckung erklärt wurde (§ 121).", "Falsch. § 121 gilt nur für §§ 119, 120. Für § 123 gilt die Jahresfrist des § 124. Das ist die eigentliche Falle der Aufgabe."], ["wirksam, weil die Jahresfrist ab Entdeckung gewahrt ist.", "Richtig. Anfechtungsgrund ist eine arglistige Täuschung (§ 123 I Alt. 1): V hat auf eine ausdrückliche Frage bewusst gelogen, und K hat deshalb gekauft. Die Frist beträgt nach § 124 I ein Jahr ab Entdeckung (§ 124 II), also vom 02.02.2022 bis zum 02.02.2023. Die Anfechtung am 03.08.2022 ist fristgerecht."], ["schwebend unwirksam, bis V zustimmt.", "Falsch. Schwebende Unwirksamkeit ist eine Kategorie z. B. für Verträge Minderjähriger (§ 108). Eine Anfechtung ist entweder wirksam oder nicht."], ["wirksam, verpflichtet K aber zum Ersatz des Vertrauensschadens (§ 122).", "Falsch. § 122 gilt nicht bei § 123."], ["unwirksam, weil die Frist ab Vertragsschluss läuft und überschritten ist.", "Falsch. Die Frist läuft ab Entdeckung (§ 124 II); auch ab Vertragsschluss wäre sie nicht überschritten."]]}, "13": {"c": 2, "o": [["F hat vertragliche Ansprüche aus einem Bewirtungsvertrag gegen R.", "Falsch. Ein Bewirtungsvertrag ist noch nicht geschlossen, F hat noch nicht bestellt. Es besteht nur ein vorvertragliches Schuldverhältnis nach § 311 II Nr. 2, das „vertragsähnlich“ ist, aber nicht vertraglich."], ["F hat keine deliktischen Ansprüche gegen R, weil er sich wegen S exkulpieren kann.", "Falsch. Die Begründung passt nicht: S ist als selbstständiger Schreiner nicht weisungsgebunden, also kein Verrichtungsgehilfe. § 831 ist schon gar nicht anwendbar, sodass es keine „Exkulpation“ gibt. Eine Haftung des R aus § 823 I wegen eigener Verkehrspflichtverletzung scheitert eher daran, dass R die Prüfung sorgfältig an einen Fachbetrieb delegiert hat."], ["F kann von R Schmerzensgeld verlangen, obwohl sie noch nichts bestellt hatte.", "Richtig. Anspruch aus §§ 280 I, 311 II Nr. 2, 241 II: R schuldete F Schutz ihrer Rechtsgüter. Die Pflichtverletzung, ein unsicherer Stuhl, ist verwirklicht. Das Verschulden des S, der die Sicherheitsprüfung übersah, wird R nach § 278 zugerechnet, weil S im Pflichtenkreis des R gegenüber den Gästen tätig wurde. Schmerzensgeld folgt aus § 253 II, das bei jeder Körperverletzung gilt, auch vertraglich."], ["F hat Ansprüche aus culpa in contrahendo gegen den Schreiner S.", "Falsch. Zwischen F und S gibt es keine Vertragsanbahnung. S wollte keinen Vertrag mit F schließen. In Betracht kommt nur § 823 I gegen S."], ["F hat gegen R nur Ansprüche, wenn R selbst den Nagel übersehen hat.", "Falsch. Das Verschulden des S wird R nach § 278 zugerechnet."], ["F bekommt von R nur die Behandlungskosten, Schmerzensgeld gibt es nur aus Delikt.", "Falsch. § 253 II gilt auch für vertragliche und vorvertragliche Ansprüche."]]}, "14": {"c": 3, "o": [["U hat gegen S einen Anspruch auf Vertragsschluss, weil die Einigung fast vollständig war.", "Falsch. Bis zur Unterschrift herrscht Abschlussfreiheit. Einen Kontrahierungszwang gibt es nicht, die c.i.c. gibt nur einen Anspruch auf das negative Interesse."], ["U hat gegen S einen Anspruch aus § 823 I wegen des Abbruchs der Verhandlungen.", "Falsch. U hat einen reinen Vermögensschaden (Zinsen). Das Vermögen ist kein von § 823 I geschütztes Rechtsgut, auch kein „sonstiges Recht“. Eine vorsätzliche sittenwidrige Schädigung (§ 826) ist nicht ersichtlich."], ["U hat keinen Anspruch gegen S, weil ihm kein Schaden entstanden ist.", "Falsch. Die Zinsen für einen Kredit, den U nur wegen des erwarteten Kaufs aufgenommen hat, sind ein Vermögensschaden."], ["U hat gegen S einen Anspruch aus c.i.c. auf Erstattung der Kreditzinsen.", "Richtig. §§ 280 I, 311 II Nr. 1, 241 II: Es gab Vertragsverhandlungen. S hat in zurechenbarer Weise das Vertrauen auf den sicheren Vertragsschluss erweckt (Einigung bevorstehend, Kredit „in Rücksprache mit S“) und die Verhandlungen ohne triftigen Grund abgebrochen. Ein verschwiegenes Konkurrenzangebot ist kein triftiger Grund. Zu ersetzen ist das negative Interesse, also die Zinsen."], ["U hat einen Anspruch aus c.i.c., aber nur auf den entgangenen Gewinn aus dem Start-up.", "Falsch. Die c.i.c. ersetzt das negative Interesse, nicht den Gewinn aus dem nie geschlossenen Vertrag."], ["U hat keinen Anspruch, weil S als Verkäufer frei an einen besser Bietenden verkaufen darf.", "Falsch. S durfte abbrechen, haftet aber, weil er zurechenbar Vertrauen erweckt und ohne triftigen Grund abgebrochen hat."]]}, "15": {"c": 0, "o": [["wirksam, auch wenn A den Ring nicht mehr liefern kann.", "Richtig. Es liegt eine anfängliche Unmöglichkeit vor (Diebstahl vor Vertragsschluss, Stückschuld). Nach § 311a I ist der Vertrag wirksam. A wird nach § 275 I (Unvermögen) frei, B nach § 326 I. Schadensersatz nach § 311a II schuldet A nur, wenn er das Hindernis kannte oder kennen musste. Hier hat A den Ring ordnungsgemäß verwahrt und den Diebstahl nicht bemerkt, also wohl kein Anspruch."], ["nichtig, weil die Leistung schon bei Vertragsschluss unmöglich war.", "Falsch. Das war die alte Rechtslage vor 2002 (§ 306 a. F.). Heute bestimmt § 311a I ausdrücklich, dass es der Wirksamkeit nicht entgegensteht, wenn das Leistungshindernis schon bei Vertragsschluss vorlag."], ["schwebend unwirksam, bis der Ring wieder auftaucht.", "Falsch. Schwebende Unwirksamkeit setzt ein noch ausstehendes Wirksamkeitserfordernis voraus, z. B. die Genehmigung nach § 108. Daran fehlt es."], ["wirksam, A kann ihn aber wegen Irrtums über den Besitz anfechten.", "Falsch. A hat sich allenfalls über seine eigene Leistungsfähigkeit geirrt. Das ist ein unbeachtlicher Motivirrtum bzw. eine Risikoverteilung, die § 311a abschließend regelt."], ["wirksam, und A muss B stets Schadensersatz statt der Leistung zahlen.", "Falsch („stets“). Nach § 311a II nur, wenn A das Hindernis kannte oder kennen musste."], ["nichtig, weil der Ring gestohlen und damit abhandengekommen ist (§ 935).", "Falsch. § 935 betrifft den gutgläubigen Erwerb, nicht die Wirksamkeit des Kaufvertrags."]]}, "16": {"c": 5, "o": [["Bei Unmöglichkeit wird der Schuldner nach § 275 I von allen Pflichten befreit.", "Falsch. § 275 I befreit nur von der Primärleistungspflicht. Sekundärpflichten bleiben, z. B. Schadensersatz (§ 275 IV) und die Herausgabe des Surrogats (§ 285)."], ["Bei anfänglicher Unmöglichkeit ist und bleibt der Vertrag unwirksam.", "Falsch. § 311a I: Der Vertrag ist wirksam."], ["Erlischt die Leistungspflicht nach § 275 I, erlischt ausnahmslos auch die Gegenleistungspflicht.", "Falsch. Das Wort „ausnahmslos“ ist das Warnsignal. Ausnahmen sind § 326 II (Verantwortung des Gläubigers, Annahmeverzug), §§ 446, 447 (Gefahrübergang) und § 326 III (Surrogat)."], ["Beim relativen Fixgeschäft wird die Leistung mit Zeitablauf unmöglich.", "Falsch. Sie bleibt nachholbar; der Gläubiger kann ohne Frist zurücktreten (§ 323 II Nr. 2)."], ["§ 275 II befreit den Schuldner automatisch, ohne dass er sich darauf beruft.", "Falsch. § 275 II und III sind Einreden; nur § 275 I wirkt kraft Gesetzes."], ["Beim absoluten Fixgeschäft führt die Nichteinhaltung der Leistungszeit zur Unmöglichkeit.", "Richtig. Beim absoluten Fixgeschäft ist die Einhaltung der Leistungszeit so wesentlich, dass eine verspätete Leistung keine Erfüllung mehr ist (Taxi zum Flughafen, Brautkleid zur Hochzeit). Mit Zeitablauf tritt Unmöglichkeit ein (§ 275 I). Abgrenzung: Beim relativen Fixgeschäft ist eine Nachholung möglich, der Gläubiger kann aber ohne Fristsetzung zurücktreten (§ 323 II Nr. 2)."]]}, "17": {"c": 1, "o": [["S hat weiter einen Lieferanspruch, muss aber den Kaufpreis nicht zahlen.", "Falsch. Die ersteigerte Vase ist ein bestimmtes Einzelstück, also eine Stückschuld. Mit ihrer Zerstörung ist die Lieferung unmöglich, und P ist nach § 275 I frei."], ["P und S haben gegeneinander keine Ansprüche mehr aus dem Kaufvertrag über die Vase.", "Richtig. P ist nach § 275 I frei. S ist nach § 326 I 1 frei, weil die Preisgefahr wegen § 475 II noch bei P lag. Schadensersatz (§§ 280 I, III, 283) scheidet aus, weil P den Unfall nicht zu vertreten hat. Ihn verursachte allein Z, und T ist als Transportunternehmen kein Erfüllungsgehilfe des P für die Unfallvermeidung bzw. hat selbst nicht schuldhaft gehandelt."], ["P ist von seiner Lieferpflicht frei, S muss aber weiter zahlen (§ 447).", "Falsch. Das wäre richtig, wenn § 447 anwendbar wäre. Hier liegt aber ein Verbrauchsgüterkauf vor (Powerseller = Unternehmer, Studentin für ihr WG-Zimmer = Verbraucherin). Nach § 475 II gilt § 447 nicht, weil S den Transporteur nicht selbst beauftragt hat."], ["Die Sonderregeln des Verbrauchsgüterkaufs gelten hier nicht.", "Falsch. P handelt als Powerseller gewerblich (§ 14), S als Verbraucherin (§ 13). Die Vase ist eine bewegliche Sache. Also liegt ein Verbrauchsgüterkauf vor (§ 474 I)."], ["S kann von P Schadensersatz verlangen, weil T der Erfüllungsgehilfe des P ist.", "Falsch. Den Unfall verursachte allein Z; P hat nichts zu vertreten."], ["P muss eine gleichwertige Vase liefern, weil er als Powerseller viele Vasen anbietet.", "Falsch. Die ersteigerte Vase ist ein Einzelstück (Stückschuld)."]]}, "18": {"c": 4, "o": [["A ist von der Lieferung nicht befreit, weil er den Unfall grob fahrlässig verursacht hat.", "Falsch. Die Befreiung nach § 275 I hängt nicht vom Verschulden ab. Der individuell angefertigte Tisch existiert nicht mehr, also ist die Leistung unmöglich."], ["A ist von der Lieferpflicht befreit, S muss aber den Kaufpreis bezahlen.", "Falsch. Das wäre richtig, wenn A nur leicht fahrlässig gehandelt hätte (§§ 300 I, 326 II 1 Fall 2), vergleiche Fall 26."], ["Keiner der beiden ist von seiner Leistungspflicht aus dem Vertrag befreit.", "Falsch. A ist nach § 275 I frei, S nach § 326 I."], ["S muss zahlen, weil sie im Annahmeverzug war und die Gefahr damit voll bei ihr liegt.", "Falsch. Im Annahmeverzug haftet A weiter für grobe Fahrlässigkeit (§ 300 I); § 326 II greift nicht."], ["A ist von der Lieferpflicht befreit, und S muss wegen der groben Fahrlässigkeit nicht zahlen.", "Richtig. A ist nach § 275 I frei. S war zwar im Annahmeverzug (tatsächliches Angebot am vereinbarten Tag in der Wohnung, § 294, Nichtannahme, § 293). Nach § 300 I haftet A im Annahmeverzug aber noch für Vorsatz und grobe Fahrlässigkeit. Hier handelte A grob fahrlässig, also hat er den Untergang zu vertreten. Damit greift § 326 II 1 Fall 2 nicht (er verlangt einen vom Schuldner NICHT zu vertretenden Umstand). Es bleibt bei § 326 I: S muss nicht zahlen."], ["A muss einen neuen Tisch anfertigen, weil er den Untergang zu vertreten hat.", "Falsch. Die Leistung ist unmöglich (§ 275 I); Vertretenmüssen führt nur zu Schadensersatz."]]}, "19": {"c": 0, "o": [["Nein, weil V den Untergang durch Blitzschlag nicht zu vertreten hat.", "Richtig. In Betracht kommt §§ 280 I, III, 283 (nachträgliche Unmöglichkeit). Dafür muss V die Unmöglichkeit zu vertreten haben (§ 280 I 2). Ein Blitzschlag ist höhere Gewalt, und V trifft kein Verschulden. Eine fehlende Versicherung ist keine Pflichtverletzung gegenüber K. Ein Beschaffungsrisiko hat V als Antiquar bei einem Einzelstück nicht übernommen. Kein Anspruch."], ["Ja, auf das positive Interesse (Erfüllungsinteresse) in Höhe von 200 €.", "Falsch. Die Berechnung stimmt (1.000 € − 800 €), wäre ein Anspruch gegeben. Es fehlt aber am Vertretenmüssen."], ["Ja, auf das negative Interesse (Vertrauensinteresse) in Höhe von 100 €.", "Falsch. Erstens fehlt das Vertretenmüssen. Zweitens wäre bei §§ 280, 283 das positive Interesse zu ersetzen und nicht das negative (900 € − 800 €)."], ["Unabhängig vom Schadensersatz kann K von V Nachlieferung der Goetheausgabe verlangen.", "Falsch. Die Ausgabe war bei V nur einmal vorhanden, also eine Stückschuld. Mit der Vernichtung ist der Lieferanspruch nach § 275 I erloschen. V muss sich auch keine Ausgabe am Markt beschaffen."], ["Ja, weil V den Band nicht gegen Brand versichert hatte und damit fahrlässig handelte.", "Falsch. Eine fehlende Versicherung ist keine Pflichtverletzung gegenüber K."], ["Ja, in Höhe von 1.000 €, weil K sich die Ausgabe neu beschaffen muss.", "Falsch. Selbst bei Vertretenmüssen wäre nur die Differenz zum Kaufpreis (200 €) zu ersetzen."]]}, "20": {"c": 5, "o": [["Nein, weil V von seiner Leistungspflicht frei geworden ist und damit auch die Gegenleistung entfällt.", "Falsch. Das ist der Grundsatz des § 326 I, aber § 447 I ist die Ausnahme: Die Preisgefahr ist auf K übergegangen."], ["Nein, weil § 447 hier wegen eines Verbrauchsgüterkaufs nicht anwendbar ist.", "Falsch. Zwischen zwei Privatleuten gibt es keinen Verbrauchsgüterkauf, es fehlt der Unternehmer als Verkäufer (§ 474 I). § 475 II ist nicht anwendbar."], ["Ja, weil der Erfüllungsort beim V lag und K die Vase dort hätte abholen müssen.", "Falsch. Das Ergebnis „Ja“ stimmt, die Begründung nicht. Die Parteien haben eine Versendung vereinbart, also musste K nicht abholen. Der Erfüllungsort beim V ist zwar Voraussetzung des § 447, aber nicht die Begründung des Anspruchs."], ["Nein, weil V die Versandkosten getragen hat und damit eine Bringschuld vereinbart war.", "Falsch. Die Übernahme der Versandkosten macht keine Bringschuld (§ 269 III)."], ["Ja, aber nur zur Hälfte, weil keiner der beiden den Unfall verschuldet hat.", "Falsch. Nach § 447 I trägt K die volle Preisgefahr."], ["Ja, weil mit der Übergabe an den Transporteur die Preisgefahr auf K übergegangen ist.", "Richtig. Versendungskauf nach § 447 I: Auf Verlangen des Käufers wird an einen anderen Ort als den Erfüllungsort versandt. Mit der Auslieferung an die Transportperson geht die Preisgefahr über. Dass V die Kosten trägt, ändert nach § 269 III nichts daran, dass der Erfüllungsort beim Verkäufer bleibt."]]}, "21": {"c": 4, "o": [["Nur dann, wenn V den Brand vorsätzlich oder grob fahrlässig verursacht hat.", "Falsch. Das ist der Maßstab des § 300 I (Annahmeverzug), nicht der des Schuldnerverzugs."], ["Nein, denn K kann von V weiterhin die Lieferung des Bildes verlangen.", "Falsch. Das Original ist verbrannt, also ist die Lieferung unmöglich (§ 275 I)."], ["Nein, in keinem Fall, weil V am Brand keinerlei Verschulden trifft.", "Falsch. Ohne den Verzug wäre das richtig. Der Verzug verschärft aber die Haftung."], ["Ja, aber nur den Verzögerungsschaden bis zum Brand, nicht den Wert des Bildes.", "Falsch. Nach § 287 S. 2 haftet V für die Unmöglichkeit; ersetzt wird der Schaden statt der Leistung (§§ 280 I, III, 283)."], ["Ja, denn V hat die Unmöglichkeit der Leistung im Verzug zu vertreten (§ 287 S. 2).", "Richtig. Nach § 287 S. 2 haftet der Schuldner während des Verzugs auch für Zufall. Das Vertretenmüssen wird also fingiert, es sei denn, der Schaden wäre auch bei rechtzeitiger Leistung eingetreten. Hätte V rechtzeitig geliefert, hinge das Bild bei K und wäre nicht verbrannt. Anspruch aus §§ 280 I, III, 283 in Verbindung mit § 287 S. 2."], ["Nein, weil der Brand höhere Gewalt war und den Verzug beendet hat.", "Falsch. Höhere Gewalt beendet den Verzug nicht; § 287 S. 2 erfasst gerade Zufall."]]}, "22": {"c": 1, "o": [["A ist in Annahmeverzug, weil er den Baum nicht rechtzeitig abgeholt hat.", "Falsch. Vereinbart war eine Bringschuld („zu A liefert“). Ein ordnungsgemäßes Angebot setzt deshalb das tatsächliche Anbieten bei A voraus (§ 294). Ein Anruf „Sie können abholen“ ist kein ordnungsgemäßes Angebot. A musste nicht abholen."], ["B befindet sich im Verzug und muss weiterhin einen gleichwertigen Baum an A liefern.", "Richtig. Der Anspruch auf Lieferung war am 20.12. fällig, und die Leistungszeit war kalendermäßig bestimmt, sodass eine Mahnung entbehrlich ist (§ 286 II Nr. 1). Hohe Nachfrage entlastet B nicht, denn bei einer Gattungsschuld trägt er das Beschaffungsrisiko (§ 276 I). B ist im Verzug, und der Lieferanspruch besteht fort."], ["Es liegt eine Stückschuld vor, weil sich die Vorratsschuld durch das Bereitstellen konkretisiert hat (§ 243 II).", "Falsch. Bei einer Bringschuld tritt die Konkretisierung erst ein, wenn die Ware beim Gläubiger angeboten wird. Das bloße Bereitstellen im Laden reicht nicht."], ["Die Leistung ist dem B nach dem Verkauf des Baumes unmöglich geworden.", "Falsch. Es handelt sich um eine (Vorrats-)Gattungsschuld, und vergleichbare Bäume sind noch vorhanden. Der Verkauf des einen Baums macht die Leistung nicht unmöglich."], ["B muss nicht liefern, weil A den Baum nicht abgeholt hat und dadurch auf die Lieferung verzichtet hat.", "Falsch. Ein Verzicht liegt nicht vor; A musste nicht abholen."], ["B ist wegen der hohen Nachfrage entschuldigt und daher nicht im Verzug (§ 286 IV).", "Falsch. Bei einer Gattungsschuld trägt B das Beschaffungsrisiko (§ 276 I)."]]}, "23": {"c": 2, "o": [["Ja, weil B nach der Mahnung in Verzug war.", "Falsch. Selbst wenn Verzug vorläge (bei Gattungsschuld wegen des Beschaffungsrisikos naheliegend), gibt der Verzug nur den Verzugsschaden neben der Leistung (§§ 280 I, II, 286). Die Mehrkosten des Deckungskaufs ersetzen die Leistung, das ist Schadensersatz statt der Leistung."], ["Ja, weil A dem B nach der Mahnung noch eine angemessene Frist zur Lieferung gelassen hat.", "Falsch. Bloßes Abwarten ist keine Fristsetzung. § 281 I verlangt, dass der Gläubiger dem Schuldner eine Frist bestimmt."], ["Nein, schon weil A dem B keine Frist zur Lieferung gesetzt hatte.", "Richtig. Der Deckungskauf-Mehrpreis ist Schadensersatz statt der Leistung (§§ 280 I, III, 281). Dafür ist eine erfolglos abgelaufene angemessene Frist erforderlich. Eine Mahnung ist keine Fristsetzung. Das Wort „schon“ zeigt: Auf die Verschuldensfrage kommt es gar nicht mehr an."], ["Ja, weil eine Nachfristsetzung hier entbehrlich war.", "Falsch. Keiner der Fälle des § 281 II liegt vor: keine ernsthafte und endgültige Verweigerung, keine besonderen Umstände. Auch ein Fixgeschäft ist nicht ersichtlich."], ["Nein, weil B den Stoffengpass nicht verschuldet hat und deshalb nie haftet.", "Falsch („nie“). Bei der Gattungsschuld trägt B das Beschaffungsrisiko; entscheidend ist hier aber schon die fehlende Frist."], ["Ja, aber nur zur Hälfte, weil A über einen Monat bis zum Deckungskauf gewartet hat.", "Falsch. Es fehlt schon an der Frist nach § 281 I."]]}, "24": {"c": 3, "o": [["Nein, weil A erst mit dem Anwaltsschreiben in Verzug geriet.", "Falsch. Eine Mahnung war entbehrlich, weil die Leistungszeit kalendermäßig bestimmt war (§ 286 II Nr. 1). A war schon ab dem 02.12. im Verzug."], ["Nein, weil A noch innerhalb der gesetzten Frist geliefert hat.", "Falsch. A hat innerhalb der Frist für Schadensersatz statt der Leistung geliefert, aber nicht rechtzeitig im Sinne des Vertrags (01.12.). Der Verzugsschaden bleibt bestehen."], ["Nur wenn A auf die Mahnung nicht geliefert und der Anwalt eine weitere Nachfrist gesetzt hätte.", "Falsch. Eine Nachfrist ist nur für Schadensersatz statt der Leistung (§ 281) und Rücktritt (§ 323) erforderlich, nicht für den Verzugsschaden."], ["Ja, weil A schon in Verzug war, als ihn das Schreiben erreichte.", "Richtig. Anspruch aus §§ 280 I, II, 286. Der Verzug trat ohne Mahnung mit Ablauf des 01.12. ein (§ 286 II Nr. 1). Die Rechtsanwaltskosten sind danach entstanden und adäquat kausal durch den Verzug verursacht. Damit sind sie ersatzfähiger Verzugsschaden. Vertretenmüssen wird vermutet (§ 286 IV)."], ["Ja, aber nur, wenn K den A vorher selbst gemahnt hat.", "Falsch. Bei kalendermäßig bestimmter Leistungszeit ist keine Mahnung nötig (§ 286 II Nr. 1)."], ["Nein, weil Anwaltskosten nur bei Verbrauchern ersatzfähig sind.", "Falsch. Eine solche Einschränkung gibt es nicht."]]}, "25": {"c": 3, "o": [["nach wie vor einen Anspruch auf Lieferung des Ferraris, da A den Verkehrsunfall verschuldet hat.", "Falsch. Ein gebrauchter Ferrari Dino ist eine Stückschuld. Er ist zerstört, also § 275 I, unabhängig vom Verschulden."], ["keinen Anspruch auf Ersatz der Garagenmiete, weil er A keine Nachfrist gesetzt hat.", "Falsch. Bei Unmöglichkeit ist eine Fristsetzung sinnlos und deshalb nicht erforderlich (§ 283 S. 1 verweist nicht auf § 281 I)."], ["keinerlei Ansprüche gegen A, weil der Ferrari zerstört ist.", "Falsch, siehe d."], ["einen Anspruch auf Ersatz der Garagenmiete von 100 € (§ 284).", "Richtig. B kann anstelle des Schadensersatzes statt der Leistung Ersatz vergeblicher Aufwendungen verlangen (§ 284). Die Garagenmiete hat B im Vertrauen auf den Erhalt des Ferraris gemacht, und sie war billigerweise gerechtfertigt. Voraussetzung ist ein Anspruch auf Schadensersatz statt der Leistung (§§ 280 I, III, 283), also nachträgliche Unmöglichkeit, die A zu vertreten hat (überhöhte Geschwindigkeit)."], ["einen Anspruch auf Ersatz der Garagenmiete nur, wenn er den Ferrari schon bezahlt hatte.", "Falsch. § 284 setzt keine Kaufpreiszahlung voraus."], ["einen Anspruch auf die Garagenmiete und zusätzlich auf den vollen Wert des Ferraris.", "Falsch. Aufwendungsersatz gibt es nur „anstelle“ des Schadensersatzes statt der Leistung (§ 284)."]]}, "26": {"c": 2, "o": [["V hat gegen K einen durchsetzbaren Kaufpreisanspruch aus § 326 II 1 Fall 1.", "Falsch. Fall 1 verlangt, dass der Gläubiger (K) für den Umstand, der zur Unmöglichkeit führte, allein oder weit überwiegend verantwortlich ist. Den Unfall hat V verursacht, nicht K."], ["V hat gegen K einen durchsetzbaren Kaufpreisanspruch aus § 326 II 1 Fall 2.", "Nach überwiegender Lesart falsch. Fall 2 setzt voraus, dass V den Untergang nicht zu vertreten hat. Im Annahmeverzug haftet V nur für Vorsatz und grobe Fahrlässigkeit (§ 300 I). „Rasen“ aus Ärger mit einem Lastwagen spricht für grobe Fahrlässigkeit, dann hätte V den Untergang zu vertreten und kein Kaufpreisanspruch bestünde (§ 326 I). Sieht man nur „passt kurz nicht auf“ (leichte Fahrlässigkeit), wäre b vertretbar. Wegen dieser Unsicherheit ist c die eindeutig richtige Antwort."], ["K befindet sich im Annahmeverzug, obwohl ihn kein Verschulden trifft (§§ 293 ff.).", "Richtig. Die Leistung war erfüllbar, V hat sie zum vereinbarten Zeitpunkt am vereinbarten Ort tatsächlich angeboten (§ 294), und K hat sie nicht angenommen (§ 293). Ein Verschulden des Gläubigers ist für den Annahmeverzug nicht erforderlich. § 299 greift nicht, weil die Leistungszeit fest bestimmt war."], ["K befindet sich nicht im Annahmeverzug, weil ihn kein Verschulden trifft.", "Falsch. Annahmeverzug ist verschuldensunabhängig. Das ist der zentrale Unterschied zum Schuldnerverzug (§ 286 IV)."], ["K befindet sich nicht im Annahmeverzug, weil V die Lieferung nicht vorher angekündigt hat (§ 299).", "Falsch. § 299 gilt nur bei unbestimmter Leistungszeit; hier war ein Termin vereinbart."], ["V haftet im Annahmeverzug für jede Fahrlässigkeit beim Rücktransport.", "Falsch. Nach § 300 I nur für Vorsatz und grobe Fahrlässigkeit."]]}, "27": {"c": 4, "o": [["nur, wenn er den Mangel vorsätzlich herbeigeführt hat.", "Falsch. Vorsatz ist für die Nacherfüllung irrelevant."], ["nur bei Vorsatz und grober Fahrlässigkeit.", "Falsch. Das ist der Maßstab des § 300 I bzw. des § 521 (Schenkung)."], ["bei Vorsatz und jeder Fahrlässigkeit (§ 276).", "Falsch. Das ist der Maßstab des § 276 I für den Schadensersatz."], ["nur, wenn er den Mangel kannte oder kennen musste.", "Falsch. Kenntnis spielt für die Nacherfüllung keine Rolle."], ["ohne Rücksicht auf ein Verschulden des Verkäufers.", "Richtig. §§ 437 Nr. 1, 439 enthalten kein Verschuldenserfordernis. Der Verkäufer hat die mangelfreie Sache versprochen (§ 433 I 2) und muss dieses Versprechen erfüllen, auch wenn er den Mangel nicht kennen konnte. Verschulden ist nur für den Schadensersatz (§ 437 Nr. 3) relevant."], ["nur, wenn er dafür eine Garantie übernommen hat.", "Falsch. Die Nacherfüllung folgt aus dem Gesetz (§§ 437 Nr. 1, 439)."]]}, "28": {"c": 5, "o": [["Für Ansprüche des A gegen H muss man unterscheiden, ob der Fehler in Hard- oder Software liegt.", "Falsch. Ein Rasenroboter ist eine Ware mit digitalen Elementen (§ 327a III). Für sie gilt einheitlich Kaufrecht, Fehler der Software sind Sachmängel der Ware."], ["Es liegt kein Sachmangel vor, weil nicht die Hardware, sondern die Software fehlerhaft ist.", "Falsch. Die Software ist Teil der Ware. Ohne sie kann der Roboter seine Funktion nicht erfüllen."], ["Selbst bei einem Mangel hat A keine Ansprüche, weil er den Roboter ständig überwachen muss.", "Falsch. Gerade das selbstständige Mähen ohne Aufsicht ist der Sinn des Produkts. Ein Mitverschulden (§ 254) könnte allenfalls beim Schadensersatz eine Rolle spielen (offene Terrassentür), schließt die Gewährleistung aber nicht aus."], ["A muss sich wegen des Softwarefehlers an den Softwarehersteller halten, nicht an H.", "Falsch. Vertragspartner ist H; bei Waren mit digitalen Elementen gilt einheitlich Kaufrecht."], ["Es liegt ein Mangel vor, A hat aber nur Ansprüche nach den §§ 327 ff.", "Falsch. Für Waren mit digitalen Elementen gelten die §§ 327 ff. nicht (§ 327a III)."], ["Der Rasenroboter entspricht nicht den subjektiven Anforderungen an die Sache.", "Richtig. Nach § 434 II 1 Nr. 2 muss sich die Sache für die nach dem Vertrag vorausgesetzte Verwendung eignen. Vorausgesetzt war, dass der Roboter den Rasen mäht und dabei im Rasenbereich bleibt. Ein Roboter, der ins Haus fährt, eignet sich dafür nicht. Daneben fehlt auch die Eignung für die gewöhnliche Verwendung (§ 434 III)."]]}, "29": {"c": 1, "o": [["Der Vertrag richtet sich in erster Linie nach den Vorschriften über digitale Produkte (§§ 327 ff.).", "Falsch. Nach § 327a III sind die §§ 327 ff. auf Kaufverträge über Waren mit digitalen Elementen gerade nicht anzuwenden. Es gilt Kaufrecht mit den §§ 475b ff."], ["K hat gegen V einen Anspruch auf die Software-Updates, die den vertragsgemäßen Betrieb sichern.", "Richtig. § 475b III Nr. 2 bzw. IV Nr. 2: Der Unternehmer (Verkäufer) muss dem Verbraucher Aktualisierungen bereitstellen, die für den Erhalt der Vertragsmäßigkeit erforderlich sind, und zwar über den Zeitraum, den der Verbraucher erwarten kann. Bei dauerhafter Bereitstellung gilt das für den gesamten Bereitstellungszeitraum."], ["Die Vorschriften über Verträge über Waren mit digitalen Elementen sind hier nicht anwendbar.", "Falsch. Das Fahrzeug kann seine hochautomatisierten Funktionen ohne die Software nicht erfüllen, also ist es eine Ware mit digitalen Elementen (§ 327a III 1). K ist Verbraucher, V Unternehmer, also gilt § 475b."], ["Nur H als Hersteller, nicht V als Verkäufer trifft die Aktualisierungspflicht.", "Falsch. Vertragspartner und Schuldner ist V. Dass V die Updates tatsächlich über H bereitstellen lässt, ändert daran nichts. V kann bei H Rückgriff nehmen (§ 478)."], ["Die Aktualisierungspflicht endet mit Ablauf der zweijährigen Gewährleistungsfrist.", "Falsch. Bei dauerhafter Bereitstellung gilt sie für den gesamten Bereitstellungszeitraum, sonst so lange, wie der Verbraucher erwarten kann (§ 475b IV)."], ["V muss Updates nur liefern, wenn K sie gesondert bezahlt.", "Falsch. Die Aktualisierung gehört zur vertragsgemäßen Leistung (§ 475b)."]]}, "30": {"c": 0, "o": [["Gewährleistungsrechte, weil der Wagen bei Gefahrübergang schon einen Motorschaden hatte.", "Richtig. Ein 6 Monate alter Wagen mit Motorschaden entspricht nicht den objektiven Anforderungen (§ 434 III 1 Nr. 2), denn er weist nicht die übliche Beschaffenheit auf. Der Mangel lag laut Sachverhalt schon bei Übergabe vor, ohnehin würde § 477 I das vermuten. Der Ausschluss „so, wie das Fahrzeug ist“ ist im Verbrauchsgüterkauf (A Unternehmer, S Verbraucherin) nach § 476 I unwirksam."], ["keine Gewährleistungsrechte, weil das Fahrzeug bei Gefahrübergang keinen Sachmangel hatte.", "Falsch. Dass der Schaden noch nicht spürbar war, ist unerheblich. Es kommt auf das Vorliegen des Mangels an, nicht auf seine Erkennbarkeit."], ["keine Gewährleistungsrechte, weil A die Gewährleistung wirksam ausgeschlossen hat.", "Falsch. Im Verbrauchsgüterkauf ist ein solcher Ausschluss nach § 476 I 1 unwirksam. Eine negative Beschaffenheitsvereinbarung nach § 476 I 2 setzt eine eigene Information über das konkrete Merkmal und eine ausdrückliche, gesonderte Vereinbarung voraus. Dass das Fahrzeug aus einer Leasingflotte stammt, ist keine Abrede über einen Motorschaden."], ["keine Gewährleistungsrechte, weil über die Beschaffenheit des Motors nichts vereinbart war.", "Falsch. Fehlt eine Beschaffenheitsvereinbarung, gelten nach § 434 I die objektiven Anforderungen trotzdem, und zwar kumulativ."], ["Gewährleistungsrechte nur, wenn A den Motorschaden kannte (§ 444).", "Falsch. Im Verbrauchsgüterkauf ist der Ausschluss schon nach § 476 I unwirksam; auf Kenntnis kommt es nicht an."], ["keine Gewährleistungsrechte, weil S als ausländische Studentin kein Verbraucher ist.", "Falsch. Verbraucher ist jede natürliche Person, die zu privaten Zwecken handelt (§ 13)."]]}, "31": {"c": 4, "o": [["U hat gegen A einen Anspruch auf Nacherfüllung.", "Falsch. Eine Nachbesserung ist unmöglich, denn die Laufleistung lässt sich nicht rückgängig machen. Eine Ersatzlieferung ist unmöglich, denn das Fahrzeug ist wegen der Sonderausstattung einmalig. Der Anspruch ist nach § 275 I ausgeschlossen."], ["Es liegt ein Fall der nachträglichen Unmöglichkeit der Nacherfüllung vor.", "Falsch. Die Laufleistung war schon bei Vertragsschluss falsch, also ist der Mangel anfänglich unbehebbar (qualitative anfängliche Unmöglichkeit). Für den Schadensersatz wäre deshalb § 311a II einschlägig."], ["U ist im vorliegenden Fall auf ein Minderungsrecht beschränkt.", "Falsch. U kann wählen zwischen Rücktritt und Minderung. Eine Beschränkung auf die Minderung gäbe es nur bei unerheblichem Mangel (§ 323 V 2), hier ist der Mangel aber erheblich."], ["U kann erst zurücktreten, wenn er A eine Frist zur Lieferung eines anderen BMW gesetzt hat.", "Falsch. Das Fahrzeug ist einmalig; die Nacherfüllung ist unmöglich (§ 326 V)."], ["U kann ohne Fristsetzung vom Kaufvertrag zurücktreten.", "Richtig. §§ 437 Nr. 2, 326 V: Ist die Nacherfüllung unmöglich, kann der Käufer ohne Fristsetzung zurücktreten. Der Mangel (80.000 statt vereinbarter 15.000 km, § 434 II) ist erheblich (§ 323 V 2). Verschulden ist für den Rücktritt nicht nötig, deshalb schadet es nicht, dass A nichts wusste. Bei einem beiderseitigen Handelsgeschäft muss U aber unverzüglich gerügt haben (§ 377 HGB)."], ["U hat keine Rechte, weil A die falsche Laufleistung nicht kannte.", "Falsch. Rücktritt und Minderung setzen kein Verschulden voraus."]]}, "32": {"c": 3, "o": [["K muss C Gelegenheit geben, ein veganes Essen nachzuliefern, und ihm eine Frist setzen.", "Falsch. Das Buffet war für die Geburtstagsfeier an genau diesem Tag bestellt, also ein absolutes Fixgeschäft. Eine spätere Nachlieferung wäre sinnlos, die Nacherfüllung ist unmöglich (§ 275 I). Eine Fristsetzung ist entbehrlich (§ 326 V)."], ["M haftet als Angestellter des C gegenüber K nicht für den verschmutzten Teppich.", "Falsch. M haftet persönlich aus § 823 I: Er hat das Eigentum der K (Teppich) fahrlässig beschädigt. Dass er Angestellter ist, schützt ihn im Außenverhältnis nicht. Im Innenverhältnis kann ihn C nach den Grundsätzen des innerbetrieblichen Schadensausgleichs ggf. freistellen."], ["C haftet gegenüber K nicht für die Verschmutzung des Bodens durch M.", "Falsch. C haftet vertraglich aus §§ 280 I, 241 II, 278 (M ist Erfüllungsgehilfe bei der Lieferung, Schutzpflicht für Eigentum der K). Daneben haftet er deliktisch aus § 831 I. Eine Exkulpation scheitert, weil C wusste, dass M schusselig ist, und ihn trotzdem einsetzte."], ["K muss das Catering nicht bezahlen, weil eine Nacherfüllung nicht mehr möglich ist.", "Richtig. Geliefert wurde nicht das Vereinbarte (vegan), sondern ein aliud bzw. eine mangelhafte Leistung (§ 434 II, V). Eine Nacherfüllung ist wegen des Fixcharakters unmöglich. K kann deshalb ohne Fristsetzung zurücktreten (§§ 437 Nr. 2, 326 V) bzw. ist nach § 326 I frei. Sie muss nicht zahlen."], ["K muss den vollen Preis zahlen, weil vegetarisches Essen kein Mangel ist.", "Falsch. Vereinbart war vegan; die Abweichung ist ein Mangel (§ 434 II)."], ["C haftet für M nur, wenn er sich nicht nach § 831 I 2 entlasten kann.", "Falsch. Vertraglich haftet C ohne Entlastung über § 278; zudem kannte C die Schusseligkeit des M."]]}, "33": {"c": 5, "o": [["Sport Schreck, weil ihm sogar ein zweiter Reparaturversuch zusteht.", "Falsch. § 440 S. 2 regelt nur, dass eine Nachbesserung nach dem zweiten erfolglosen Versuch als fehlgeschlagen gilt. Ein Recht des Verkäufers auf zwei Versuche folgt daraus nicht. Außerdem hat Sport Schreck noch nicht einmal den ersten Versuch abgeschlossen."], ["Sport Schreck, weil Kevin wegen des Abholscheins bis zur Reparatur warten musste.", "Falsch. Der Abholschein ist nur eine Quittung und keine Vereinbarung über einen Verzicht auf Mängelrechte. Ein solcher Verzicht wäre im Verbrauchsgüterkauf vor Mitteilung des Mangels ohnehin nach § 476 I unwirksam."], ["Keiner der beiden hat mit seiner Auffassung Recht.", "Falsch, Kevin hat Recht."], ["Sport Schreck, weil Kevin zunächst ausdrücklich eine Frist hätte setzen müssen.", "Falsch. Beim Verbrauchsgüterkauf genügt der Ablauf einer angemessenen Frist ab Unterrichtung über den Mangel (§ 475d I Nr. 1)."], ["Sport Schreck, weil Kevin statt des Rücktritts nur mindern darf, solange repariert wird.", "Falsch. Nach Ablauf der angemessenen Frist kann Kevin zwischen Rücktritt und Minderung wählen (§ 475d I Nr. 1)."], ["Kevin, denn die Voraussetzungen für den Rücktritt sind gegeben.", "Richtig. Es handelt sich um einen Verbrauchsgüterkauf (Sport Schreck = Unternehmer, Kevin privat). Seit 01.01.2022 gilt § 475d I Nr. 1: Der Verbraucher kann ohne Fristsetzung zurücktreten, wenn der Unternehmer nach Ablauf einer angemessenen Frist ab dem Zeitpunkt, zu dem der Verbraucher ihn über den Mangel unterrichtet hat, die Nacherfüllung nicht vorgenommen hat. Kevin hat den Mangel mitgeteilt, und eine angemessene Frist ist abgelaufen. Der Mangel ist erheblich (Rollen fallen ab)."]]}, "34": {"c": 1, "o": [["Karla ist durch ihre Nachricht wirksam vom Kauf zurückgetreten.", "Falsch. Ein Rücktritt setzt einen Rücktrittsgrund voraus, etwa einen Mangel und eine Frist nach §§ 437 Nr. 2, 323. „Zu klein“ ist kein Mangel, wenn die Größe so bestellt war. Die Erklärung wirkt aber als Widerruf."], ["Victoria erstattet Kaufpreis und Hinsendekosten, Karla schuldet Wertersatz für die Flecken.", "Richtig. Die Erklärung ist als Widerruf auszulegen (§§ 312g I, 355 I). Folge: Erstattung des Kaufpreises und der Kosten der Standard-Hinsendung (§ 357 I, II). Das Tragen im Café und die Flecken sind ein Umgang, der zur Prüfung der Ware nicht nötig war. Karla muss Wertersatz leisten (§ 357a I)."], ["Karla bekommt den Kaufpreis erstattet, alle Versandkosten muss Victoria tragen.", "Falsch, weil unvollständig und teilweise unrichtig. Victoria trägt nur die Hinsendekosten (§ 357 II), die Rücksendekosten trägt grundsätzlich Karla (§ 357 V). Vor allem fehlt der Wertersatz für die Flecken (§ 357a I)."], ["Der Widerruf wirkt nur, wenn das Kleid binnen 14 Tagen ab Erhalt bei Victoria eintrifft.", "Falsch. Zur Fristwahrung genügt nach § 355 I 5 die rechtzeitige Absendung der Widerrufserklärung. Es kommt nicht auf den Eingang an."], ["Karla hat kein Widerrufsrecht mehr, weil sie das Kleid schon getragen hat.", "Falsch. Das Tragen schließt den Widerruf nicht aus, es führt nur zu Wertersatz (§ 357a I)."], ["Karla muss für die Flecken keinen Ersatz leisten, weil sie sie nicht vorsätzlich verursacht hat.", "Falsch. Wertersatz nach § 357a I setzt kein Verschulden voraus."]]}, "35": {"c": 0, "o": [["Karla kann den Vertrag ohne jede Begründung widerrufen.", "Richtig. Es handelt sich um einen Fernabsatzvertrag (Webshop, Verbraucherin gegen Unternehmerin, § 312c). Karla hat ein Widerrufsrecht nach §§ 312g I, 355. Die Frist von 14 Tagen ab Erhalt (§ 356 II Nr. 1a) läuft noch („einige Tage“). Der Widerruf bedarf nach § 355 I 4 keiner Begründung. Das Widerrufsrecht besteht neben den Mängelrechten."], ["Karla kann von Victoria den geforderten Umtausch in eine andere Größe verlangen.", "Falsch. Nacherfüllung durch Ersatzlieferung (§ 439 I) bedeutet: dieselbe Sache in mangelfreiem Zustand. Ein Kleid in einer anderen Größe ist eine andere Sache. Dass das Kleid zu klein ist, ist kein Mangel, denn die Größe war ja bestellt. Einen Anspruch auf die größere Größe gibt es nur über einen neuen Vertrag."], ["Karla kann wählen, ob sie widerruft oder sofort den Kaufpreis mindert.", "Falsch. Die Minderung erfolgt „statt zurückzutreten“ (§ 441 I) und setzt deshalb die Rücktrittsvoraussetzungen voraus, insbesondere eine erfolglose Frist zur Nacherfüllung. Das Vorrangprinzip der Nacherfüllung gilt auch hier. Eine sofortige Minderung ist nicht möglich."], ["Karla tritt durch ihre Nachricht wegen des Mangels wirksam vom Vertrag zurück.", "Falsch. Die Nachricht verlangt gerade die Zusendung eines anderen Kleides, also ein Nacherfüllungsverlangen und keine Lösung vom Vertrag. Außerdem fehlt die erfolglose Fristsetzung zur Nacherfüllung."], ["Karla kann nicht widerrufen, weil sie Mängelrechte geltend gemacht hat.", "Falsch. Widerrufsrecht und Mängelrechte bestehen nebeneinander."], ["Karla kann nur widerrufen, wenn sie den Mangel nachweist.", "Falsch. Der Widerruf braucht keinen Grund (§ 355 I 4)."]]}, "36": {"c": 2, "o": [["Für die Einbeziehung müsste V in der Auftragsbestätigung erneut auf seine AGB verweisen.", "Falsch. Der Hinweis muss bei Vertragsschluss erfolgen, und er ist hier bereits im Angebot ausdrücklich erfolgt. Ein erneuter Hinweis in der Auftragsbestätigung ist nicht erforderlich."], ["K hätte den AGB durch einen besonderen Vermerk auf der Bestellung ausdrücklich zustimmen müssen.", "Falsch. Das Einverständnis (§ 305 II a. E.) kann konkludent erklärt werden. Die Bestellung „zu den im Angebot genannten Bedingungen“ genügt."], ["V hätte K ermöglichen müssen, zumutbar von den AGB Kenntnis zu nehmen, etwa durch Zusendung.", "Richtig. § 305 II Nr. 2 verlangt, dass die andere Vertragspartei in zumutbarer Weise vom Inhalt Kenntnis nehmen kann. Einem Kunden in München ist es nicht zumutbar, nach Stuttgart zu fahren. Bei einem Distanzgeschäft hätte V die AGB übersenden oder beifügen müssen. Die AGB sind nicht einbezogen, der Vertrag gilt ohne sie (§ 306)."], ["AGB sind immer nur dann einbezogen, wenn sie dem Kunden ausgehändigt werden.", "Falsch. Es genügt die Möglichkeit zumutbarer Kenntnisnahme. Ein Aushändigen ist eine, aber nicht die einzige Möglichkeit (Link, Abdruck auf der Rückseite, Aushang)."], ["Die AGB sind einbezogen, weil K sie im Geschäft in Stuttgart hätte einsehen können.", "Falsch. Für einen Kunden in München ist das nicht zumutbar (§ 305 II Nr. 2)."], ["Die AGB sind einbezogen, weil K mit der Bestellung „zu den genannten Bedingungen“ auf die Kenntnisnahme verzichtet hat.", "Falsch. Darin liegt kein Verzicht auf die Möglichkeit zumutbarer Kenntnisnahme (§ 305 II Nr. 2)."]]}, "37": {"c": 0, "o": [["Der Hinweis in der App ist eine AGB-Haftungsbegrenzung, die Vertragsbestandteil geworden ist.", "Richtig, bezogen auf die Einbeziehung. Der Hinweis ist eine für eine Vielzahl von Verträgen vorformulierte, von V gestellte Vertragsbedingung (§ 305 I). Er steht gut lesbar unmittelbar vor dem Bestellbutton, also bei Vertragsschluss. K schließt mit Kenntnis ab. Gegenüber dem Unternehmer K genügt das (§ 310 I), es wären sogar die strengeren Anforderungen des § 305 II erfüllt. „Vertragsbestandteil geworden“ betrifft die Einbeziehung. Ob die Klausel der Inhaltskontrolle standhält, ist eine zweite Frage (BGH: Kardinalpflicht, § 307 II Nr. 2)."], ["Ist K Unternehmer, gibt es keine rechtlichen Anforderungen an die Einbeziehung von AGB.", "Falsch. § 310 I nimmt nur § 305 II, III aus. Eine (auch konkludente) rechtsgeschäftliche Einbeziehungsvereinbarung bleibt erforderlich. Außerdem gilt § 305c."], ["§ 312j verdrängt bei Verbrauchern die Regeln über die Einbeziehung von AGB.", "Falsch. § 312j regelt besondere Pflichten im elektronischen Geschäftsverkehr mit Verbrauchern (Button-Lösung, Informationspflichten). Er tritt neben die §§ 305 ff. und verdrängt sie nicht."], ["Bei einem Firmenwagen reicht für die Haftungsbegrenzung ein gut sichtbares Schild an der Ausfahrt.", "Falsch. Ein Hinweis nach Vertragsschluss und nach Erbringung der Leistung kann nicht mehr Vertragsinhalt werden, auch nicht im B2B-Verkehr. Die Einigung muss bei Vertragsschluss erfolgen."], ["Der Hinweis ist keine AGB, weil er nur auf einem Bildschirm und nicht auf Papier steht.", "Falsch. Auch digitale, vorformulierte Bedingungen sind AGB (§ 305 I)."], ["Der Hinweis ist unwirksam, weil jede Haftungsbegrenzung in AGB gegenüber Unternehmern verboten ist.", "Falsch. Gegenüber Unternehmern gilt nur § 307; eine Begrenzung für leichte Fahrlässigkeit bei Sachschäden ist nicht generell verboten."]]}, "38": {"c": 5, "o": [["Auch im stationären Handel besteht grundsätzlich ein Widerrufsrecht nach § 312g.", "Falsch. § 312g I gewährt das Widerrufsrecht nur bei Außergeschäftsraum- und Fernabsatzverträgen. Im Laden kann der Kunde die Ware prüfen, deshalb ist er nicht schutzbedürftig."], ["Die Widerrufsfrist nach § 312g beginnt immer mit dem Vertragsschluss.", "Falsch. § 355 II 2 nennt den Vertragsschluss nur als Grundsatz, § 356 II verschiebt den Beginn beim Warenkauf auf den Erhalt der Ware. Außerdem beginnt die Frist nicht vor ordnungsgemäßer Belehrung (§ 356 III)."], ["Fällt der Fristbeginn auf einen Sonntag, beginnt die Widerrufsfrist erst am Montag.", "Falsch. § 193 verschiebt nur das Fristende, nicht den Beginn. Eine Frist kann an einem Sonntag beginnen (Fall 39: Beginn am Sonntag, 8. Mai)."], ["Der Widerruf ist nur wirksam, wenn der Verbraucher einen Grund angibt.", "Falsch. Eine Begründung ist nicht erforderlich (§ 355 I 4)."], ["Ohne ordnungsgemäße Belehrung kann der Verbraucher zeitlich unbegrenzt widerrufen.", "Falsch. Spätestens nach 12 Monaten und 14 Tagen erlischt das Recht (§ 356 III 2)."], ["Fehlt eine ordnungsgemäße Widerrufsbelehrung, beginnt die Frist zunächst nicht.", "Richtig. § 356 III 1: Die Frist beginnt nicht, bevor der Unternehmer den Verbraucher ordnungsgemäß belehrt hat (Art. 246a § 1 II EGBGB). Spätestens erlischt das Widerrufsrecht aber nach 12 Monaten und 14 Tagen (§ 356 III 2). Daher das Wort „zunächst“."]]}, "39": {"c": 2, "o": [["Klaudia kann den Vertrag bis Montag, 16. Mai 2022, 24 Uhr widerrufen.", "Falsch. Der 16. Mai wäre richtig, wenn man ab Bestellung (1. Mai) rechnet und auf den nächsten Werktag verschiebt. Beim Warenkauf beginnt die Frist aber erst mit Erhalt (§ 356 II Nr. 1a)."], ["Klaudia kann den Vertrag nicht mehr widerrufen.", "Falsch. Es liegt ein Fernabsatzvertrag vor, kein Ausschlussgrund nach § 312g II (Modeschmuck ist weder individuell angefertigt noch eine Hygieneware). Die Frist läuft noch."], ["Die Widerrufsfrist läuft am Montag, dem 23. Mai 2022, ab.", "Richtig. Erhalt am Sa 07.05. (Ereignis, § 187 I), also Fristbeginn am So 08.05. Nach 14 Tagen endet die Frist am Sa 21.05. (§ 188 II). Weil das ein Samstag ist, verschiebt § 193 das Ende auf den nächsten Werktag, Mo 23.05.2022."], ["Klaudia hat lediglich einen Anspruch auf Umtausch, nicht auf Widerruf.", "Falsch. Ein gesetzliches Umtauschrecht gibt es nicht. Das Gesetz gibt ein Widerrufsrecht."], ["Die Widerrufsfrist lief am Samstag, dem 21. Mai 2022, ab.", "Falsch. Fällt das Fristende auf einen Samstag, verschiebt § 193 es auf den Montag."], ["Die Widerrufsfrist beginnt erst mit dem Auspacken am 21. Mai 2022.", "Falsch. Maßgeblich ist der Erhalt der Ware (§ 356 II Nr. 1 a)."]]}, "40": {"c": 4, "o": [["Donnerstag, 13. Juli 2023", "Falsch. Dieses Ergebnis entsteht, wenn man den Ereignistag (7. Juli) fälschlich mitzählt. § 187 I schließt ihn aus."], ["Samstag, 15. Juli 2023", "Falsch. Das wäre der 8. Tag."], ["Montag, 17. Juli 2023", "Falsch. Das wäre richtig, wenn das Fristende auf Samstag oder Sonntag fiele (§ 193). Das ist nicht der Fall."], ["Mittwoch, 12. Juli 2023", "Falsch. Das wären nur fünf Tage nach Eingang."], ["Freitag, 14. Juli 2023", "Richtig. Der Eingang der Bestellung am Fr 07.07. um 10 Uhr ist ein Ereignis im Lauf des Tages, also zählt der Tag nicht mit (§ 187 I). Fristbeginn am Sa 08.07. Der 7. Tag ist Fr 14.07., die Frist endet mit dessen Ablauf (§ 188 I). Freitag ist ein Werktag, § 193 greift nicht."], ["Dienstag, 18. Juli 2023", "Falsch. So käme man nur, wenn man sieben Werktage zählt; gemeint sind Kalendertage."]]}, "41": {"c": 3, "o": [["Nein, weil die Zerstörung der Brille keine Folge des Faustschlags ist.", "Falsch. Ohne den Faustschlag wäre die Brille nicht zerstört (Äquivalenz). Die Zerstörung einer Brille bei einem Schlag ins Gesicht liegt nicht außerhalb jeder Lebenserfahrung (Adäquanz)."], ["Nein, weil für immaterielle Schäden grundsätzlich kein Geld geschuldet ist.", "Falsch. § 253 II gewährt bei Verletzung des Körpers und der Gesundheit ausdrücklich eine billige Entschädigung in Geld."], ["Nein, weil B durch das Einlassen auf den Streit in die Verletzung eingewilligt hat.", "Falsch. Wer sich auf einen verbalen Streit einlässt, willigt nicht konkludent in eine Körperverletzung ein. Eine Einwilligung bräuchte einen erkennbaren Willen, das Risiko eines Faustschlags hinzunehmen (anders etwa beim Boxkampf)."], ["Ja, B kann Krankenhauskosten, eine neue Brille und Schmerzensgeld verlangen.", "Richtig. § 823 I: Verletzung von Körper (Nasenbein) und Eigentum (Brille) durch vorsätzlichen Faustschlag, rechtswidrig und schuldhaft. Schaden: Behandlungskosten und Brille (§§ 249 ff.), dazu Schmerzensgeld (§ 253 II). Zugleich ergibt sich der Anspruch aus § 823 II in Verbindung mit § 223 StGB."], ["Ja, aber nur Krankenhaus und Brille; Schmerzensgeld gibt es nur bei bleibenden Schäden.", "Falsch. § 253 II setzt keinen Dauerschaden voraus."], ["Ja, aber gekürzt um 50 %, weil B den Streit mitverursacht hat (§ 254).", "Falsch. Ein verbaler Streit ist kein Mitverschulden an einem vorsätzlichen Faustschlag."]]}, "42": {"c": 1, "o": [["§ 831 und § 278 sind beides eigenständige Anspruchsgrundlagen.", "Falsch. Nur § 831 ist eine Anspruchsgrundlage. § 278 ist eine Zurechnungsnorm im bestehenden Schuldverhältnis und wird mit § 280 I kombiniert."], ["Der Verrichtungsgehilfe ist immer weisungsgebunden; das unterscheidet ihn vom Selbstständigen.", "Richtig. Die Weisungsgebundenheit ist gerade das Merkmal, das den Verrichtungsgehilfen definiert: Der Geschäftsherr kann Zeit, Ort und Art der Tätigkeit bestimmen. Wer nicht weisungsgebunden ist, ist begrifflich kein Verrichtungsgehilfe, sondern ein selbstständiger Unternehmer."], ["Der Geschäftsherr haftet nach § 831 nur, wenn der Verrichtungsgehilfe schuldhaft handelt.", "Falsch. § 831 setzt nur eine „widerrechtliche“ Schadenszufügung voraus. Der Geschäftsherr haftet für eigenes, vermutetes Auswahl- oder Überwachungsverschulden."], ["Auch beim Erfüllungsgehilfen ist ein Entlastungsbeweis möglich.", "Falsch. § 278 rechnet das Gehilfenverschulden wie eigenes zu, eine Entlastung ist nicht vorgesehen. Das ist der zentrale Vorteil des Vertragsrechts für den Geschädigten."], ["Ein selbstständiger Handwerker ist stets Verrichtungsgehilfe seines Auftraggebers.", "Falsch. Ihm fehlt gerade die Weisungsgebundenheit."], ["§ 278 setzt voraus, dass zwischen Geschäftsherrn und Geschädigtem kein Schuldverhältnis besteht.", "Falsch. Umgekehrt: § 278 setzt ein Schuldverhältnis voraus."]]}, "43": {"c": 4, "o": [["V schuldet K keinen Schadensersatz, weil er nur Verrichtungsgehilfe ist.", "Falsch. Der Verrichtungsgehilfe haftet selbst aus § 823 I für sein eigenes fahrlässiges Verhalten. § 831 ist eine zusätzliche Haftung des Geschäftsherrn und befreit den Gehilfen nicht."], ["U haftet für V nur, wenn V grob fahrlässig oder vorsätzlich gehandelt hat.", "Falsch. § 831 verlangt nicht einmal ein Verschulden des V, und § 278 rechnet jede Fahrlässigkeit zu."], ["K hat keinen Anspruch wegen der Kopfschmerzen, weil immaterielle Schäden nicht ersetzt werden.", "Falsch. § 253 II gewährt Schmerzensgeld bei Körperverletzung."], ["U kann sich entlasten, weil er V bei der Einstellung sorgfältig ausgewählt hat.", "Falsch. U kontrolliert praktisch nie, obwohl V schon mehrfach ungeschickt war; die Entlastung scheitert an der Überwachung."], ["U muss K Schadensersatz leisten; eine Entlastung scheidet hier aus.", "Richtig. Deliktisch haftet U aus § 831 I 1: V ist als Angestellter Verrichtungsgehilfe, hat den Körper des K widerrechtlich verletzt, und zwar in Ausführung der Verrichtung. Die Entlastung nach § 831 I 2 scheitert, weil U praktisch nie kontrolliert und V schon mehrfach ungeschickt war. Daneben haftet U vertraglich bzw. aus c.i.c. (§§ 280 I, 241 II, 278), dort ist eine Exkulpation von vornherein ausgeschlossen."], ["K muss sich an V halten, weil U selbst nicht gehandelt hat.", "Falsch. U haftet aus § 831 und über § 278; V haftet daneben."]]}, "44": {"c": 3, "o": [["Ja, weil die AGB wirksam Vertragsbestandteil geworden sind.", "Falsch. Selbst wenn sie einbezogen sind, scheitern sie an der Inhaltskontrolle."], ["Ja, weil der Schadensersatz nicht für alle Fälle ausgeschlossen ist.", "Falsch. Gerade für Körperschäden ist jeder Ausschluss oder jede Begrenzung unwirksam, egal wie eng er formuliert ist."], ["Nein, weil sich der Kunde mit den AGB ausdrücklich einverstanden erklären muss.", "Falsch. Das Ergebnis „Nein“ stimmt, die Begründung nicht. Das Einverständnis kann konkludent erfolgen. Eine ausdrückliche Zustimmung ist nicht nötig."], ["Nein, weil ein Ausschluss der Haftung für Körperschäden in AGB unwirksam ist.", "Richtig. § 309 Nr. 7 a: In AGB ist ein Ausschluss oder eine Begrenzung der Haftung für Schäden aus der Verletzung des Lebens, des Körpers oder der Gesundheit, die auf einer fahrlässigen Pflichtverletzung des Verwenders oder seiner Erfüllungsgehilfen beruhen, unwirksam. Die Klausel fällt weg (§ 306), und es bleibt bei der gesetzlichen Haftung."], ["Ja, weil K die AGB zur Kenntnis genommen und damit akzeptiert hat.", "Falsch. Einbeziehung heißt nicht Wirksamkeit; die Klausel scheitert an § 309 Nr. 7 a."], ["Nein, aber nur für vorsätzlich verursachte Verletzungen.", "Falsch. § 309 Nr. 7 a erfasst schon fahrlässige Verletzungen des Körpers."]]}, "45": {"c": 0, "o": [["P hat keine vertraglichen Ansprüche gegen A und B, sondern nur deliktische.", "Richtig. Zwischen dem Passanten P und den Arbeitnehmern A und B besteht weder ein Vertrag noch ein vorvertragliches Schuldverhältnis. Es bleiben deliktische Ansprüche (§ 823 I, § 823 II in Verbindung mit § 229 StGB)."], ["A und B haften P nicht, wenn sie nachweisen, dass sie sonst sorgfältig arbeiten.", "Falsch. Eine Exkulpation gibt es nur für den Geschäftsherrn nach § 831 I 2, nicht für den Täter selbst. A und B haften aus § 823 I für ihr eigenes fahrlässiges Verhalten (Bretter fallen lassen, Alkohol bei der Arbeit). Wie sie „normalerweise“ arbeiten, ist irrelevant."], ["P hat keine deliktischen Ansprüche gegen G, weil G selbst kein Delikt begangen hat.", "Falsch. § 831 I begründet eine eigene deliktische Haftung des G für sein vermutetes Auswahl- und Überwachungsverschulden. Daneben kommt § 823 I wegen Verletzung eigener Verkehrssicherungspflichten (Absicherung der Baustelle) in Betracht."], ["P kann in dieser Situation nur vertragliche Ansprüche gegen G geltend machen.", "Falsch. P ist ein zufälliger Passant und hat keinen Vertrag mit G. Ein Vertrag mit Schutzwirkung zugunsten Dritter scheitert, weil P nicht in Leistungsnähe zum Bauvertrag steht. Es bleiben deliktische Ansprüche."], ["P hat vertragliche Ansprüche gegen G aus einem Vertrag mit Schutzwirkung für Dritte.", "Falsch. P steht als zufälliger Passant nicht in Leistungsnähe."], ["A und B haften nicht, weil der Alkohol ihre Deliktsfähigkeit ausgeschlossen hat (§ 827).", "Falsch. „Ein paar Bierchen“ schließen die freie Willensbestimmung nicht aus; zudem gilt § 827 S. 2."]]}, "46": {"c": 5, "o": [["K hat gegen H keinen Anspruch aus § 1 ProdHaftG.", "Falsch. Für das Garagentor besteht ein Anspruch: eine andere Sache als das Produkt, gewöhnlich privat genutzt (§ 1 I 2), Fabrikationsfehler (§ 3), H ist Hersteller (§ 4). Nach Abzug der Selbstbeteiligung von 500 € (§ 11) bleiben 700 €. Für das Auto selbst gibt es keinen Anspruch aus dem ProdHaftG."], ["K hat gegen V einen Anspruch aus § 823 I.", "Falsch. V ist nur Händler. Ihm fällt keine eigene Verkehrspflichtverletzung zur Last, denn ein Händler muss Neuwagen nicht auf versteckte Produktionsfehler untersuchen. Gegen V bestehen Gewährleistungsrechte aus § 437."], ["Ein Anspruch aus § 823 I ist neben einem Anspruch aus § 1 ProdHaftG ausgeschlossen.", "Falsch. § 15 II ProdHaftG: Eine Haftung aufgrund anderer Vorschriften bleibt unberührt. Beide Ansprüche bestehen nebeneinander."], ["Nach dem ProdHaftG bekommt K 3.700 € für Auto und Garagentor.", "Falsch. Das Produkt selbst ist nicht erfasst, und es gilt eine Selbstbeteiligung von 500 € (§ 11)."], ["Nach § 823 I muss K dem H ein Verschulden nachweisen, ohne Beweiserleichterung.", "Falsch. Bei der Produzentenhaftung muss der Hersteller nach der Rechtsprechung sein fehlendes Verschulden beweisen."], ["Liegen die Voraussetzungen des § 823 I vor, gibt es keine Haftungsbegrenzung.", "Richtig. Die deliktische Produzentenhaftung kennt weder eine Selbstbeteiligung (anders § 11 ProdHaftG) noch einen Haftungshöchstbetrag (anders § 10 ProdHaftG). Der Schaden ist nach §§ 249 ff. voll zu ersetzen. Deshalb ist § 823 I trotz Verschuldenserfordernis praktisch wichtig. Die Beweislast für das fehlende Verschulden trägt nach der Rechtsprechung der Hersteller."]]}, "47": {"c": 2, "o": [["Mit dem wirksamen notariellen Kaufvertrag wird der Käufer Eigentümer des Grundstücks.", "Falsch. Der Kaufvertrag ist das Verpflichtungsgeschäft und überträgt kein Eigentum. Dafür sind Auflassung und Eintragung nötig (§§ 873 I, 925)."], ["Ist der Grundstückskaufvertrag unwirksam, kann der Käufer unter keinen Umständen Eigentümer werden.", "Falsch. Das Abstraktionsprinzip gilt auch bei Grundstücken. Bei Formnichtigkeit des Kaufvertrags tritt sogar Heilung durch Auflassung und Eintragung ein (§ 311b I 2). „Unter keinen Umständen“ ist das Warnsignal."], ["Der Käufer wird mit Auflassung und Eintragung Eigentümer, auch wenn der Kaufvertrag unwirksam ist.", "Richtig. Das sind die Voraussetzungen des § 873 I in Verbindung mit § 925: dingliche Einigung (Auflassung) und Eintragung, außerdem die Berechtigung des Veräußerers. Wegen des Abstraktionsprinzips kommt es auf den Kaufvertrag nicht an. Fehlt dieser, besteht ein Anspruch auf Rückübertragung aus § 812 I 1 Alt. 1."], ["Haus und Grundstück müssen in gesonderten dinglichen Verträgen übereignet werden.", "Falsch. Das Haus ist wesentlicher Bestandteil des Grundstücks (§§ 93, 94 I) und kann nicht Gegenstand besonderer Rechte sein. Es geht automatisch mit dem Grundstück über."], ["Die Auflassung kann formfrei erklärt werden, nur der Kaufvertrag braucht den Notar.", "Falsch. Die Auflassung muss vor einer zuständigen Stelle erklärt werden (§ 925 I)."], ["Eigentümer wird der Käufer schon mit Übergabe der Schlüssel.", "Falsch. Bei Grundstücken ersetzt die Eintragung die Übergabe (§ 873)."]]}, "48": {"c": 1, "o": [["Eigentümer des Grundstücks ist K, weil er zuerst gekauft hat.", "Falsch. Der zeitlich frühere Kaufvertrag verschafft kein Eigentum."], ["Eigentümer des Grundstücks ist weiterhin E, weil noch keiner eingetragen ist.", "Richtig. Beide Kaufverträge sind nur Verpflichtungsgeschäfte und ändern nichts an der Eigentumslage (Trennungsprinzip). Weder K noch G hat eine Auflassung und Eintragung erreicht (§§ 873, 925). E ist weiterhin Eigentümer."], ["Eigentümer des Grundstücks ist G, weil er gutgläubig ist.", "Falsch. Auch G hat nur einen Kaufvertrag. Die Gutgläubigkeit spielt keine Rolle, denn E ist ohnehin Berechtigter."], ["Eigentum wird durch Zahlung erworben; Eigentümer wird, wer zuerst zahlt.", "Falsch. Die Zahlung ist die Erfüllung der Käuferpflicht (§ 433 II) und hat mit dem Eigentumserwerb am Grundstück nichts zu tun."], ["K und G sind Miteigentümer, weil beide formwirksam gekauft haben.", "Falsch. Kaufverträge übertragen kein Eigentum."], ["Der zweite Kaufvertrag ist nichtig, weil E das Grundstück schon verkauft hatte.", "Falsch. Auch ein Doppelverkauf ist wirksam; E haftet dann einem Käufer."]]}, "49": {"c": 0, "o": [["G kann Eigentümer werden, sobald Auflassung und Eintragung erfolgt sind.", "Richtig. §§ 873 I, 925: E ist als Eigentümer berechtigt. Erklären E und G die Auflassung und wird G eingetragen, wird G Eigentümer, unabhängig vom früheren Vertrag mit K. Nur eine Vormerkung zugunsten des K (§ 883) hätte das verhindert."], ["G kann kein Eigentum erwerben, weil E zuerst mit K einen Vertrag geschlossen hat.", "Falsch. Im Schuldrecht gibt es kein Prioritätsprinzip. Der Vertrag mit K ist ein relatives Recht und bindet nur E, nicht G. E bleibt verfügungsbefugt."], ["Wird G Eigentümer, kann K von G Ersatz der Mehrkosten für ein anderes Grundstück verlangen.", "Falsch. Zwischen K und G besteht kein Schuldverhältnis. Eine Forderung ist kein „sonstiges Recht“ im Sinne des § 823 I. § 826 scheidet aus, weil G gutgläubig ist. K kann nur gegen E vorgehen (§§ 280 I, III, 283)."], ["Auflassung ist die notarielle Beurkundung des Grundstückskaufvertrags.", "Falsch. Auflassung ist die dingliche Einigung über den Eigentumsübergang an einem Grundstück (§ 925 I), erklärt bei gleichzeitiger Anwesenheit vor einer zuständigen Stelle (Notar). Die Beurkundung des Kaufvertrags folgt aus § 311b I und ist das Verpflichtungsgeschäft."], ["G wird nur Eigentümer, wenn K vorher zustimmt.", "Falsch. Der Vertrag mit K bindet nur E; G braucht keine Zustimmung."], ["K kann von E die Übereignung verlangen, auch wenn G bereits eingetragen ist.", "Falsch. Dann ist E die Leistung unmöglich (§ 275 I); K bleibt Schadensersatz (§§ 280 I, III, 283)."]]}, "50": {"c": 1, "o": [["Wer Voreigentümer ist, spielt keine Rolle, weil § 929 nur Einigung und Übergabe verlangt.", "Falsch. Weitere Voraussetzung des § 929 S. 1 ist die Berechtigung des Veräußerers. Fehlt sie, hilft nur der gutgläubige Erwerb (§ 932), und dafür kommt es gerade auf die Eigentümerstellung an."], ["Durch die Zahlung der 500 € an B ist K nicht Eigentümer geworden.", "Richtig. Die Zahlung erfüllt nur die Pflicht des K aus § 433 II. Für den Eigentumserwerb am Fahrrad braucht es Einigung und Übergabe (§ 929 S. 1). Selbst dann würde K wegen der fehlenden Berechtigung des B und seiner eigenen Bösgläubigkeit (§ 932 II, er WUSSTE es) nicht Eigentümer, außer C genehmigt (§ 185 II)."], ["K kann auch mit Genehmigung des C nicht Eigentümer werden, weil er nicht mit C kontrahiert hat.", "Falsch. Nach § 185 II 1 wird die Verfügung eines Nichtberechtigten wirksam, wenn der Berechtigte sie genehmigt. Der Kaufvertrag ist für den Eigentumserwerb irrelevant (Abstraktionsprinzip)."], ["Genehmigt C die Übereignung von B an K, darf B den Kaufpreis behalten.", "Falsch. Durch die Genehmigung wird die Verfügung des Nichtberechtigten B gegenüber C wirksam. Nach § 816 I 1 muss B das durch die Verfügung Erlangte, also die 500 €, an C herausgeben. Die Genehmigung ist gerade der Weg, über den C an den Erlös kommt."], ["K wird nach § 932 gutgläubig Eigentümer, sobald B ihm das Rad übergibt.", "Falsch. K weiß, dass B nicht Eigentümer ist; er ist bösgläubig (§ 932 II)."], ["Der Kaufvertrag zwischen B und K ist nichtig, weil B nicht Eigentümer ist.", "Falsch. Der Verkauf einer fremden Sache ist wirksam."]]}, "51": {"c": 2, "o": [["F kann nichts von K verlangen, weil K nicht sein Vertragspartner ist.", "Falsch. Durch die Abtretung tritt F an die Stelle des V als Gläubiger (§ 398 S. 2). Er kann die Forderung aus dem Kaufvertrag geltend machen, obwohl er nicht Vertragspartner ist."], ["F wird Inhaber der Forderung erst, wenn er V den Kaufpreis für sie bezahlt hat.", "Falsch. Das verwechselt Verpflichtungs- und Verfügungsgeschäft. Die Zahlung des F ist die Erfüllung des Forderungskaufs (§ 453). Die Inhaberschaft geht durch den Abtretungsvertrag (§ 398) über, unabhängig von der Zahlung."], ["F erwirbt die Forderung durch Abtretung von V; K muss nicht zustimmen.", "Richtig. § 398: Vertrag zwischen altem und neuem Gläubiger. Der Schuldner ist am Vertrag nicht beteiligt und muss nicht zustimmen. Er wird geschützt durch §§ 404, 406, 407 (Einwendungen bleiben, befreiende Zahlung an V bei Unkenntnis)."], ["Zahlt K nicht fristgerecht an F, kann F von V die Zahlung verlangen.", "Falsch. Beim echten Factoring (Forderungskauf) übernimmt der Faktor das Ausfallrisiko (Delkredere). Ein Rückgriff auf V ist nicht vorgesehen. Nur beim unechten Factoring oder bei besonderer Vereinbarung wäre das anders. Außerdem haftet der Verkäufer einer Forderung nur für ihren Bestand (Veritätshaftung), nicht für die Zahlungsfähigkeit des Schuldners."], ["Die Abtretung wird erst wirksam, wenn K von ihr benachrichtigt wurde.", "Falsch. Die Anzeige ist keine Wirksamkeitsvoraussetzung; sie schützt nur den Schuldner (§ 407)."], ["K kann gegenüber F keine Einwendungen aus dem Kaufvertrag mehr erheben.", "Falsch. Einwendungen bleiben erhalten (§ 404)."]]}, "52": {"c": 3, "o": [["A kann von B lediglich die Maschine herausverlangen; B bekommt den Kaufpreis zurück.", "Falsch, weil unvollständig. Nach § 818 I sind auch die gezogenen Nutzungen herauszugeben bzw. nach § 818 II deren Wert zu ersetzen. Das Wort „lediglich“ macht die Aussage falsch."], ["A hat gegen B Schadensersatz, weil er die Maschine eine Zeit lang nicht nutzen konnte.", "Falsch. Das Bereicherungsrecht gewährt keinen Schadensersatz, sondern schöpft die Bereicherung ab. Für Schadensersatz fehlt eine Pflichtverletzung des B. Er hat die Maschine im Glauben an einen wirksamen Vertrag benutzt."], ["A kann die Maschine und den gesamten Gewinn aus den produzierten Teilen verlangen.", "Falsch. Der Unternehmergewinn ist keine Nutzung der Maschine (§ 100), sondern beruht auf der eigenen Leistung des B (Arbeit, Material, Know-how, Kunden)."], ["A kann die Maschine und Wertersatz in Höhe der üblichen Miete verlangen.", "Richtig. § 812 I 1 Alt. 1: B hat Eigentum und Besitz an der Maschine ohne Rechtsgrund erlangt, also muss er die Maschine zurückübereignen. § 818 I: Gezogene Nutzungen sind herauszugeben, dazu gehören die Gebrauchsvorteile (§ 100). Weil man Gebrauchsvorteile nicht zurückgeben kann, schuldet B nach § 818 II Wertersatz, gemessen am objektiven Wert, also am üblichen Mietzins."], ["A kann nur nach § 985 vorgehen, weil B wegen der Unwirksamkeit nie Eigentümer wurde.", "Falsch. Abstraktionsprinzip: Die Übereignung war wirksam; A hat den Bereicherungsanspruch."], ["A kann nichts verlangen, weil B gutgläubig war und entreichert ist (§ 818 III).", "Falsch. B hat die Maschine noch und hat Gebrauchsvorteile gezogen."]]}};
Object.keys(SA).forEach(i=>{const q=A[i]; if(q&&q.o.length===4){q.o=SA[i].o;q.c=SA[i].c;}});
R.forEach(q=>{const v=SR[q.n]; if(v&&q.o.length===4){q.o=v.o;q.c=v.c;}});
window.dispatchEvent(new Event('wpr-data'));
})();
